export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-mol-0001", "section": "service", "who": "rubric", "text": "Оглавление"},
  {"id": "cu-mol-0002", "section": "service", "who": "rubric", "text": "^ Молитва ко Пресвятой Богородице благодарственная"},
  {"id": "cu-mol-0003", "section": "service", "who": "rubric", "text": "Что Ти принесем, или что Ти воздадим, о Премилостивая Госпоже Владычице, заступнице рода христианскаго, за вся Твоя неисчетная благодеяния, яже присно являеши всем призывающим имя Твое и Твоея помощи просящим. Кто бо притекаяй к Тебе посрамлен и неуслышан от Тебе отходит, о премилосердая Мати?"},
  {"id": "cu-mol-0004", "section": "service", "who": "reader", "text": "Вемы, Пречистая, яко за множество грехов и беззаконий наших несмы достойни ниже имя Твое пресладкое нарещи, не точию песнопения от оскверненных устен Тебе приносити, и удобее есть нам молчание любити. Но да не явимся непамятливи и неблагодарни пред Тобою, дерзаем приносити Тебе сие коленопреклоненное славословие: Ты же, премилосердая Мати, не возгнушайся прияти е, яко от избытка любящих Тя сердец возносимое."},
  {"id": "cu-mol-0005", "section": "service", "who": "reader", "text": "Сама Ты, Владычице, благодатию Твоею коснися сердец наших, да яко воск растаявша, пролиются пред Тобою в слезных благодарениих и славословиих."},
  {"id": "cu-mol-0006", "section": "service", "who": "reader", "text": "Благодарим Тя, Всепетая: не таим благодеяний Твоих, но велегласно возвещаем, да вси слышащии притекают к Тебе, единей непостыдней Заступнице рода христианскаго, и да немолчно славословят Тя, Всепетую, во веки веков. Аминь."},
  {"id": "cu-mol-0007", "section": "service", "who": "rubric", "text": "Молитвы пред иконами Божией Матери"},
  {"id": "cu-mol-0008", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Акафистной»"},
  {"id": "cu-mol-0009", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "cu-mol-0010", "section": "service", "who": "rubric", "text": "О Пречудная и Превысшая всех тварей Царице и Богородице, Небеснаго Царя Христа Бога нашего Мати, припадаем и поклоняемся Тебе пред святою и пречестною иконою Твоею, еюже дивныя и преславныя чудеса содеваеши!"},
  {"id": "cu-mol-0011", "section": "service", "who": "reader", "text": "Смиренно молим Тя, всесильная рода нашего Заступнице, услыши нас и удиви на нас пребогатыя милости Твоя, и прошения наша, приносимая Тебе, яко благая Скоропослушница, исполни. Благодатию Твоею души наша освяти и не отнимай от нас покрова Своего, под ним же присно пребывая, яко Стеной Нерушимей защищени пребудем от всех бед и напастей, от всякаго врага и супостата, от всех злых козней вражиих на нас присно находящих."},
  {"id": "cu-mol-0012", "section": "service", "who": "reader", "text": "Благоуханием непорочней души Своея наполни души наша, да возвеселятся сердца наша, ибо несть никто в мире сем милее и прекраснее Тебе, Дево Пресвятая! Ты еси наше Богатство, Ты еси наше Сокровище, Ты еси наше Упование и наша Защито! К Тебе Единей в печалех наших притекаем и у Тебе Единей утешение получити чаем."},
  {"id": "cu-mol-0013", "section": "service", "who": "reader", "text": "О Всепетая Дево Богородице, не престай молитися о нас, недостойных рабех Твоих, славящих Тя и почитающих, и надежду на Тебе имущих, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0014", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Ахтырской»"},
  {"id": "cu-mol-0015", "section": "service", "who": "rubric", "text": "(15 июля)"},
  {"id": "cu-mol-0016", "section": "service", "who": "rubric", "text": "О Преблагословенная и Многомилостивая Владычице мира! Се мы грешнии на святый образ Твой взирающе и на нем Тя в скорби и сострадании распятому за нас Христу Спасителю предстоящу видяще, усердно молим Тя известную о нас к Сыну Твоему молитвенницу: не остави нас в день испытания и скорби, но во искушениих и напастех нам бываемых огради нас всечестным покровом Твоим от враг видимых и невидимых и даждь нам силу, во еже всесовершенную и благую волю Творца и мира Владыки творити."},
  {"id": "cu-mol-0017", "section": "service", "who": "reader", "text": "Зриши бо, милостивая Заступнице наша, колико грехам всяческим подвержени есмы: не токмо бо волею согрешаем, но и неволею в многоразличныя прегрешения впадаем. Сего ради к Тебе державней устроительнице спасения христианскаго прибегаем и умиленно вопием: ум наш познанием Божественныя истины просвети, сердце наше теплотою христианския любви и спасительных желаний согревай, волю же нашу в нелицемерном заповедей Господних исполнении утверди."},
  {"id": "cu-mol-0018", "section": "service", "who": "reader", "text": "Ей, Госпоже Премилостивая, приникни с высоты Небесныя к воздыханием и молитве нас грешных: исцели болезни недужных, умири сердца озлобленных, даждь терпение страждущим, внуши страх Божий обидящим, укрепи гонимыя за правду, сироты и вдовы защити, подаждь утешение плачущим, испроси прощение кающимся, демонскую же бурю страстей во грешных душах утиши и в сердцах чтущих Тя Христову кротость и любовь вкорени и духом милосердия и сострадания сия утверди: отпадшыя же от веры еретики и отступники к познанию истины направи и уста нечестивых, хулящих Святую Церковь и веру православную поносящих загради."},
  {"id": "cu-mol-0019", "section": "service", "who": "reader", "text": "Отшедшим от жития сего отцем и братиям и сестрам нашим, о Мати Божия, прощение грехов и предначатие блаженства вечнаго испроси. Егда же и нашея кончины час приближится, тогда убо, о Владычице, приими душу нашу и в сонме праведных сию упокой, идеже лици Ангел и святых угодник немолчно славословят державу и милость Отца и Сына и Святаго Духа и Твое матернее о нас предстательство и заступление, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0020", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Барской»"},
  {"id": "cu-mol-0021", "section": "service", "who": "rubric", "text": "(14 октября)"},
  {"id": "cu-mol-0022", "section": "service", "who": "rubric", "text": "Богопрославленная, всемирно воспеваемая Госпоже Мати Вседержителева Богородице Марие! Приими нашу сию от полноты сердец любящих Тя, приносимую Тебе пред святою Твоею иконою молитву."},
  {"id": "cu-mol-0023", "section": "service", "who": "reader", "text": "Якоже до сего дне и часа милостиво покрывала еси вся люди, притекающия в храм сей, тако и в предняя благопоспеши нам во всех делех и начинаниих наших, яже не возбраняют нашему вечному спасению."},
  {"id": "cu-mol-0024", "section": "service", "who": "reader", "text": "Ты веси немощь нашу, зриши скорби, нужды и смущения отовсюду находящия, но вся сия можеши единым токмо воззрением Твоим умирити, аще токмо восхощеши помощи нам. Вемы, яко грех ради наших несмы достойни милосердия Твоего, но Ты, Рождшая пришедшаго в мир грешники спасти, спаси и нас на всяк день и час согрешающих."},
  {"id": "cu-mol-0025", "section": "service", "who": "reader", "text": "Укрепи слабую волю и немощное произволение наше и оживотвори нас духом истиннаго покаяния. Да тако очищении зде Твоего покрова достойни будем и с горящим светильники добродетелей в Страну Небесную прейдем невозбранно, идеже сподобимся поклонитися Тебе, Пречистая Госпоже, славяще избравшую и возвеличившую Тя Пресвятую Троицу, Отца и Сына, и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0026", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Балыкинской» («Волынской»)»"},
  {"id": "cu-mol-0027", "section": "service", "who": "rubric", "text": "(13 июля)"},
  {"id": "cu-mol-0028", "section": "service", "who": "rubric", "text": "О Мати Божия, некогда от нашествия иноверных свеев в велицей беде Отечеству нашему бывшу, явила еси всемощное заступление прославлением в стране Северстей всечестнаго образа Твоего, именуемаго Балыкинским, и зримыми на нем слезами очес Твоих умолила Сына Твоего и Бога нашего даровати православным Христианом преславную победу и одоление на супостаты."},
  {"id": "cu-mol-0029", "section": "service", "who": "reader", "text": "Ты, Премилосердная Мати, и в мимошедшия дни во граде Орле пред Пречистым образом Твоим даровала исцеление страждущей от духа нечистаго девице, возвратив ю родителем здраву и невредиму."},
  {"id": "cu-mol-0030", "section": "service", "who": "reader", "text": "Ты, скорая Помощнице в бедах человеческих, услышала вопль матери детища, с высоты жилища внезапу спадша, и возставила е здраво и безвредно."},
  {"id": "cu-mol-0031", "section": "service", "who": "reader", "text": "Ты, неизсякаемый источниче чудес и щедрот, принесенной к дивному образу Твоему отроковице зело разслабленной благоизволила даровати скорое исцеление, укрепив плесне ея к желанному хождению."},
  {"id": "cu-mol-0032", "section": "service", "who": "reader", "text": "Ты, всемощная Царице неба и земли, воздвигла от неисцельнаго недуга младенцев, их же родители притекоша к Тебе с верою и любовию."},
  {"id": "cu-mol-0033", "section": "service", "who": "reader", "text": "Ты, Подательнице мира душам нашим, избавила юношу от свирепеющих страстей и преклонила злонравие его ко благонравию и покорению родителям."},
  {"id": "cu-mol-0034", "section": "service", "who": "reader", "text": "Ты неоскудно изливала струи Своей милости на всех, притекающих к пресвятому образу Твоему в душевных скорбех, телесных недузех и житейских напастех."},
  {"id": "cu-mol-0035", "section": "service", "who": "reader", "text": "Вонми, о Всеблагая, и нынешнему усердному молению нашему: управи пути земнаго странствия нашего к мирному и благодетельному житию, украси жительство наше благими обычаи, загради всесильною дланию Твоею уста лжеучителей, вздымающихся на Разум Божий, тлящих обычаи православных предков наших и развращающих умы и сердца юных чад наших, посли нам во все дни жития нашего имети чистоту помыслов и сердечных движений."},
  {"id": "cu-mol-0036", "section": "service", "who": "reader", "text": "Сама, о, Всепетая, заступи и имиже веси судьбами спаси и введи нас в прерадостныя обители Сына Твоего и Бога нашего. Аминь."},
  {"id": "cu-mol-0037", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Белыничской»"},
  {"id": "cu-mol-0038", "section": "service", "who": "rubric", "text": "(25 апреля)"},
  {"id": "cu-mol-0039", "section": "service", "who": "rubric", "text": "О всемилостивая Госпоже Царице Богородице, от всех родов избранная и всеми роды земными и небесными ублажаемая! Припадаем, покланяемся Тебе и смиренно молим Тя: воззри милостиво на предстоящия пред святым образом Твоим чудотворным, и приими молитвы, со слезами Тебе приносимыя от нас, недостойных рабов Твоих, и к Твоему образу пение возсылаемое со умилением, яко Тебе Самой ту сущей, послушающей и подающей с верою просящим по коемуждо прошению исполнение."},
  {"id": "cu-mol-0040", "section": "service", "who": "reader", "text": "Ты, именуемая Всех скорбящих Радость, услыши нас, скорбных. Ты, называемая Утоли моя печали, утоли нашу печаль. Ты, купино неопалимая, сохрани мир и всех нас от вредоносных огненных стрел врага. Ты, взыскание погибших, не попусти нам погибнути в бездне грехов наших. Ты, Одигитрие, укажи нам правый путь ко спасению. Ты, неувядаемый цвете чистоты, даждь нам помощь, немощным плотскою страстию, и уцеломудри нас. Ты, боголюбивая скоропослушнице, услыши в час сей молитву нашу."},
  {"id": "cu-mol-0041", "section": "service", "who": "reader", "text": "Ты, заступница усердная, Мати Господа Вышняго, Ты, наша Мати и надеждо, облегчи скорбь нашу, немощным здравие даруй, разслабленных и недужных исцели и от одра болезни возстави. От бесных бесы отгони, обидимых от бед избави, вдов защити, грешныя прости, прокаженныя очисти, слепым зрение даруй, старость поддержи, юныя настави, малыя дети помилуй, неплодны от неплодства разреши, в семействах мир утверди, путешествующим спутешествуй, православным христианом на враги победу и одоление даруй, ереси и расколы изкорени, отпадшия от благочестивыя веры на путь правый обрати, страну нашу миром огради, земли плодородие даруй, всех же нас от внезапныя смерти сохрани и всякия многоразличныя страсти уврачуй, вся бо возможеши ходатайством к Сыну твоему Христу Богу нашему."},
  {"id": "cu-mol-0042", "section": "service", "who": "reader", "text": "О всепетая Мати, Пресвятая Дево Богородице, не престани молитися о нас, недостойных, и к пречистому образу Твоему со умилением припадающих и со страхом и любовию на сей взирающих, яко живей Ти сущей. Услыши нас, Владычице, на Тя по Бозе едину надежду имущих."},
  {"id": "cu-mol-0043", "section": "service", "who": "reader", "text": "Прежде отшедшия отцы и матери, братия и сестры наша упокой в селениих святых, в месте светле, в месте злачне, в месте покойне, идеже несть печаль и воздыхание. Егда же приспеет и наше от жития сего отшествие и к вечней жизни преселение, предстани нам, преблагословенная надеждо наша, даруй нам христианскую кончину живота нашего, безболезненну, непостыдну, мирну и Святых Тайн причастну, да в будущем веце сподобимся вси купно со всеми святыми безконечныя блаженныя жизни во царствии возлюбленнаго Сына Твоего Иисуса Христа, Емуже подобает всякая слава, честь и поклонение со Безначальным Его Отцем и Пресвятым, и Благим, и Животворящим Его Духом ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0044", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Благодатное Небо»"},
  {"id": "cu-mol-0045", "section": "service", "who": "rubric", "text": "(19 марта)"},
  {"id": "cu-mol-0046", "section": "service", "who": "rubric", "text": "Что Тя наречем, о, Благодатная Богомати Богоотроковице, Пренепорочная Марие? Киими песнопении возвеличим Тя, возвеличенную Небом и землею, Ангелами и человеки? Явися бо на Тебе неслышанное от века на земли и несведомое Ангелами на Небеси таинство, паче ума и слова, вочеловечения Бога Слова, рожденнаго съискони от Безначальнаго Отца без матери и воплощеннаго в Твоей утробе и с нетленною печатию девства Твоего родившагося."},
  {"id": "cu-mol-0047", "section": "service", "who": "reader", "text": "О, чудо всех древних и новых чудес! Непреложное слово Самаго Бога о победоносном семени жены и исполнися и совершися в Безмужней Деве. О, неизмеримая глубина премудрости и величия Божия!"},
  {"id": "cu-mol-0048", "section": "service", "who": "reader", "text": "Киими имены наречем Тя, о Невесто Неневестная? Зарею ли наречем Тя восходящаго на небе солнца? Но Ты – самое Небо, из Тебе бо возсия Солнце Правды – Христос Бог наш, Спаситель грешных."},
  {"id": "cu-mol-0049", "section": "service", "who": "reader", "text": "Именуем ли Тя вратами, вводящими в потерянный прародителями рай, обиловавший всеми благами? Но Ты Сама еси благодатный рай, произрастившая Цвет нетления, врачующий и отгоняющий смердение греха и зловоние прародительскаго тления."},
  {"id": "cu-mol-0050", "section": "service", "who": "reader", "text": "Наречем ли Тя юною Непорочною Девою, не познавшей брака? Но Ты и до старости пребыла Неискусобрачною и девственною до рождения, и в рождении, и по рождении Сына пребыла еси."},
  {"id": "cu-mol-0051", "section": "service", "who": "reader", "text": "Наименуем ли Тя Чистою и Святою Мариею, превозшедшею Своею чистотою всех матерей и праматерей? Но Ты не токмо родила Того Младенца Христа, но и носила Его при Своих персех, и питала Твоим матеродевственным млеком, Того, Иже питает всякое создание, Емуже со страхом и трепетом предстоят Небесныя силы и Его же хвалит всякое дыхание и тварь."},
  {"id": "cu-mol-0052", "section": "service", "who": "reader", "text": "О, воистину Ты дивная еси в женах, чудная в девах, неподражаемая в матерех! К Тебе пред Твоим Божественным ликом припадаем и пред Твоими святыми стопами повергаем и слагаем все наши мысли, желания, намерения и чувства. Освяти их Твоим Богоматерним призрением и вознеси их, яко жертву нашего смиреннаго сердца, яко малоценную лепту нашей духовной нищеты, к Престолу Сына Твоего, Спасителя нашего, да имиже весть судьбами управит наш путь ко спасению и наследию Царствия Его, не имущаго конца во веки веков. Аминь."},
  {"id": "cu-mol-0053", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Благоуханный Цвет»"},
  {"id": "cu-mol-0054", "section": "service", "who": "rubric", "text": "(28 ноября)"},
  {"id": "cu-mol-0055", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Вышши еси всех Ангел и Архангел, и всея твари честнейшая, Помощница еси обидимых, ненадеющихся надеяние, убогих Заступнице, печальных утешение, алчущих кормительнице, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление!"},
  {"id": "cu-mol-0056", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже, Дево Богородице Владычице, милостию Твоею спаси и помилуй богохранимую страну нашу, власти и воинство ея, и вся православныя христианы, ризою Твоею честною защити: и умоли, Госпоже, из Тебе без семене воплотившагося Христа Бога нашего, да препояшет нас силою Своею свыше на невидимые и видимые враги наша."},
  {"id": "cu-mol-0057", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже, Владычице Богородице, воздвигни нас из глубины греховныя и избави нас от глада, губительства, от труса и потопа, от огня и меча, от нахождения иноплеменных и междоусобныя брани, и от напрасныя смерти, и от нападения вражия, и от тлетворных ветр, и от смертоносныя язвы, и от всякаго зла."},
  {"id": "cu-mol-0058", "section": "service", "who": "reader", "text": "Подаждь, Госпоже, мир и здравие рабом Твоим, всем православным христианом, и просвети им ум и очи сердечнии, еже ко спасению: и сподоби ны, грешныя рабы Твоя, царствия Сына Твоего, Христа Бога нашего: яко держава Его благословенна, и препрославлена, со Безначальным Его Отцем, и с Пресвятым, и Благим, и Животворящим Его Духом, ныне и присно, и во веки веков, Аминь."},
  {"id": "cu-mol-0059", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Боголюбской»"},
  {"id": "cu-mol-0060", "section": "service", "who": "rubric", "text": "(1 июля)"},
  {"id": "cu-mol-0061", "section": "service", "who": "rubric", "text": "О Пречистая Госпоже Богородице, Мати Боголюбивая, надеждо нашего спасения! Воззри милостивно на предстоящия с верою и любовию и покланяющияся пречистому образу Твоему; приими наше хвалебное пение сие и пролей теплую Твою молитву о нас грешных ко Господу, да, презрев вся наша согрешения, спасет и помилует нас!"},
  {"id": "cu-mol-0062", "section": "service", "who": "reader", "text": "О Предивная Владычице! Покажи на нас чудныя милости Твоя. Молим Тя умиленно, избави нас от всякия скорби, настави на путь всякия добродетели и благостыни, спаси от искушений, бед и болезней, изми от нас оклеветания и ссоры; сохрани от молниеноснаго грома, от запаления огненнаго, от глада, труса, потопа и смертоносныя язвы; подай нам Свою милостивую помощь на пути, в мори и на суше, да не погибнем люте."},
  {"id": "cu-mol-0063", "section": "service", "who": "reader", "text": "О Всемилостивая Боголюбивая Мати, с твердым упованием возсылаем к Тебе нашу смиренную молитву! Не отрини наших слез и воздыханий, не забуди нас во вся дни живота нашего, но всегда пребывай с нами, и Твоим заступлением и ходатайством у Господа подаждь нам отраду, утешение, защиту и помощь, да выну славим и величаем Преблагословенное и Всепетое имя Твое. Аминь."},
  {"id": "cu-mol-0064", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Валаамской»"},
  {"id": "cu-mol-0065", "section": "service", "who": "rubric", "text": "(воскресенье после 12 июля)"},
  {"id": "cu-mol-0066", "section": "service", "who": "rubric", "text": "О Чудная и вышшая всех тварей Царице Богородице, Небеснаго Царя Христа Бога нашего Мати! Услыши ны грешныя и недостойныя рабы Твоя, в час сей молящияся и припадающия к Тебе со воздыханием и слезами и умильно глаголющия: изведи нас от рова страстей, Владычице, избави нас от всякия скорби и печали, огради от всякия напасти и злых клевет и от неправеднаго и лютаго навета вражия."},
  {"id": "cu-mol-0067", "section": "service", "who": "reader", "text": "Можеши бо, о, Благодатная Мати Божия, не точию от всякаго зла сохранити люди Твоя, но и всяким благодеянием снабдити их и спасти, разве Тебе иныя Предстательницы в бедах и обстояниих и теплыя Ходатаицы о нас грешных не имамы к Сыну Твоему, Христу Богу нашему. Егоже умоли, Владычице, да, спасеннии Тобою, славим в будущем веце всесвятое имя Сына Твоего и Бога нашего, купно со Отцем и Святым Духом, ныне и в безконечныя веки. Аминь."},
  {"id": "cu-mol-0068", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери Ватопедской, именуемой «Отрада» или «Утешение»"},
  {"id": "cu-mol-0069", "section": "service", "who": "rubric", "text": "(3 февраля)"},
  {"id": "cu-mol-0070", "section": "service", "who": "rubric", "text": "Надежда всем концем земли, Пречистая Дево Богородице, Утешение и Отрадо наше! Не гнушайся нас грешных, на Твою бо1 милость уповаем."},
  {"id": "cu-mol-0071", "section": "service", "who": "reader", "text": "Угаси пламень греховный и покаянием ороси изсохшие сердца наша. Очисти ум наш от греховных помышлений. Приими моления от души и сердца с воздыханием2 Тебе приносимыя."},
  {"id": "cu-mol-0072", "section": "service", "who": "reader", "text": "Буди Ходатаице о нас к Сыну Твоему и Богу и отврати гнев Его от нас Матерними молитвами. Укрепи в нас веру православную, вложи в нас дух страха Божия3, дух смирения, терпения и любви. Душевныя и телесныя язвы4 исцели, утиши5 бурю злых нападений вражеских. Отыми6 бремя грехов наших и не остави нас до конца погибнути."},
  {"id": "cu-mol-0073", "section": "service", "who": "reader", "text": "Подаждь нам милость Твою и святое благословение Свое всем зде7 предстоящим и молящимся и всегда пребывай с нами, подавая приходящим к Тебе отраду и утешение, помощь и заступление8, да славим и величаем Тя вси до последняго нашего воздыхания. Аминь."},
  {"id": "cu-mol-0074", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Взыскание погибших»"},
  {"id": "cu-mol-0075", "section": "service", "who": "rubric", "text": "(18 февраля)"},
  {"id": "cu-mol-0076", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Дево, Владычице Богородице, Споручнице9 грешных и Взыскание погибших10! Призри11 милостивным Твоим оком на нас, предстоящих пред святою иконою Твоею и со умилением12 молящихся Тебе: воздвигни нас из глубины греховныя, просвети ум наш, омраченный страстьми13, и уврачуй язвы душ и телес наших."},
  {"id": "cu-mol-0077", "section": "service", "who": "reader", "text": "Не имамы14 иныя помощи, не имамы иныя надежды, разве Тебе, Владычице: Ты веси15 вся немощи и согрешения наша. К Тебе прибегаем и вопием: не остави нас Твоею Небесною помощию, но предстани нам присно16 и Твоим неизреченным милосердием и щедротами17 спаси и помилуй нас, погибающих."},
  {"id": "cu-mol-0078", "section": "service", "who": "reader", "text": "Даруй нам исправление греховныя жизни нашея и избави нас от скорбей, бед и болезней, от внезапныя смерти, ада и вечныя муки. Ты бо еси18, Царице и Владычице, скорая Помощница и Заступница всем притекающим к Тебе и крепкое прибежище грешников кающихся."},
  {"id": "cu-mol-0079", "section": "service", "who": "reader", "text": "Подаждь убо19 нам, Преблагая и Всенепорочная Дево, христианский конец жизни нашея мирен и непостыден и сподоби20 нас Твоим ходатайством вселитися во обителех Небесных, идеже21 непрестанный глас празднующих радостию славит Пресвятую Троицу, Отца, и Сына, и Святаго Духа, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0080", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Владимирской»"},
  {"id": "cu-mol-0081", "section": "service", "who": "rubric", "text": "(3 июня, 6 июля и 8 сентября)"},
  {"id": "cu-mol-0082", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже Богородице, Небесная Царице, всемощная22 Заступнице, непостыдное наше упование! Благодарим Тя о всех благодеяниих, российским людем от Тебе бывших, отдревле23 и доднесь24 от чудотворныя иконы Твоея явленных."},
  {"id": "cu-mol-0083", "section": "service", "who": "reader", "text": "И ныне, Преблагая Владычице, призри на ны, грешныя и недостойныя рабы Твоя, яви нам милость Твою и моли Сына Твоего, Христа Бога нашего, о еже25 избавитися нам от всякаго зла и сохранитися царствующим градом, всякому граду и веси26, и всей стране нашей, от глада, губительства, труса27, потопа, огня, меча, нашествия иноплеменник и междоусобныя брани."},
  {"id": "cu-mol-0084", "section": "service", "who": "reader", "text": "Сохрани и умудри пастырей Церкве, еже достойно пасти стадо Христово и право правити28 слово истины; укрепи христолюбивое всероссийское воинство, подаждь дух совета и разума военачальником, градоначальником и всем, Иже во власти суть; низпосли святое Твое благословение и всем православным христианом, покланяющимся Ти и молящимся пред цельбоносною29 Твоею иконою."},
  {"id": "cu-mol-0085", "section": "service", "who": "reader", "text": "Буди нам Заступница и Ходатаица пред Престолом Всевышняго, идеже предстоиши. К кому убо прибегнем, аще30 не к Тебе, Владычице? Кому принесем слезы и воздыхания, аще не Тебе, Пресвятая Богородице? Не имамы бо иныя помощи, не имамы иныя надежды, разве31 Тебе, Небесная Царице."},
  {"id": "cu-mol-0086", "section": "service", "who": "reader", "text": "Под Твой покров притекаем: молитвами Твоими низпосли нам мир, здравие, земли плодоносие, воздуха благорастворение32, избави ны от всяких бед и скорбей, от всяких недугов и болезней, от внезапныя смерти и от всех озлоблений врагов видимых и невидимых."},
  {"id": "cu-mol-0087", "section": "service", "who": "reader", "text": "Вразуми и научи ны, о Всемилостивая Заступнице, путь земнаго сего жития безгрешно прейти. Ты веси немощи наша, веси и согрешения наша, но и веру веси, и упование видиши: темже33 даруй нам исправление греховныя жизни и умягчи злая сердца наша."},
  {"id": "cu-mol-0088", "section": "service", "who": "reader", "text": "Укрепи в нас правую веру, вложи в сердца наша дух страха Божия, дух благочестия, дух смирения, терпения и любве, в добрых делех преуспеяние: избави же нас от искушений, от пагубных душевредных учений, от неверия, развращения и погибели вечныя."},
  {"id": "cu-mol-0089", "section": "service", "who": "reader", "text": "Тебе убо просим, Пречистая Владычице, и припадающе пред святою Твоею иконою, молимся: умилосердися на ны и помилуй ны, в Страшный же день Суда ходатайством и заступлением Твоим сподоби ны стати одесную34 Сына Твоего, Христа Бога нашего, Емуже подобает всякая слава, честь и поклонение, со Безначальным Его Отцем, и Пресвятым и Благим и Единосущным Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0090", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Владимирской-Елецкой»"},
  {"id": "cu-mol-0091", "section": "service", "who": "rubric", "text": "(8 сентября)"},
  {"id": "cu-mol-0092", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Вышши35 еси всех Ангел и Архангел и всея твари честнейши36, помощница еси обидимых, ненадеющихся надеяние37, убогих заступница, печальных утешение, алчущих кормительница, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление."},
  {"id": "cu-mol-0093", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже, Дево Богородице Владычице! Милостию Твоею спаси и помилуй страну нашу, преосвященныя митрополиты, архиепископы и епископы, и весь священнический и иноческий чин, военачальники, градоначальники и христолюбивое воинство, и доброхоты, и вся православныя христианы ризою Твоею честною защити, и умоли, Госпоже, из Тебе без семене воплотившагося Христа Бога нашего, да препояшет нас силою Своею свыше на невидимыя и видимыя враги наша."},
  {"id": "cu-mol-0094", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже Владычице Богородице! Воздвигни нас из глубины греховныя, и избави нас от глада38, губительства, от труса и потопа, от огня и меча, от нахождения иноплеменных и междоусобныя брани, и от внезапныя смерти, и от нападения вражия, и от тлетворных ветр, и от смертоносныя язвы, и от всякаго зла."},
  {"id": "cu-mol-0095", "section": "service", "who": "reader", "text": "Подаждь, Госпоже, мир и здравие рабом Твоим, всем православным христианом, и просвети им ум и очи сердечныя еже ко спасению, и сподоби ны, грешныя рабы Твоя, Царствия Сына Твоего, Христа Бога нашего, яко Держава39 Его благословена и препрославлена, со Безначальным Его Отцем и с Пресвятым и Благим и Животворящим Его Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0096", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Воспитание»"},
  {"id": "cu-mol-0097", "section": "service", "who": "rubric", "text": "(18 марта)"},
  {"id": "cu-mol-0098", "section": "service", "who": "rubric", "text": "О, Пресвятая Владычице Дево Богородице, спаси и сохрани под кровом Твоим чад моих (имена их), всех отроков, отроковиц и младенцев, крещеных и безымянных и во чреве матере носимых. Покрый их ризою Твоего Материнства, соблюди их во страсе40 Божием и в послушании родителем, умоли Сына Твоего и Господа нашего, да дарует им полезная ко спасению их. Вручаю их Матернему смотрению41 Твоему, яко Ты еси Божественный покров рабом Твоим. Аминь."},
  {"id": "cu-mol-0099", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всех скорбящих Радость»"},
  {"id": "cu-mol-0100", "section": "service", "who": "rubric", "text": "(6 ноября)"},
  {"id": "cu-mol-0101", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице и Богородице, высшая Херувим и честнейшая Серафим, Богоизбранная Отроковице, всех скорбящих Радосте!"},
  {"id": "cu-mol-0102", "section": "service", "who": "reader", "text": "Подаждь утешение и нам, в скорби сущим42: разве бо Тебе иного прибежища и помощи не имамы. Ты едина еси радости нашея Ходатаица, и яко Мати Божия и Мати милосердия, предстоящи у Престола Пресвятыя Троицы, можеши нам помощи: никтоже бо притекаяй к Тебе посрамлен отходит."},
  {"id": "cu-mol-0103", "section": "service", "who": "reader", "text": "Услыши убо и нас, ныне в день скорби пред Твоею иконою припадающих и со слезами Тебе молящихся: отжени43 от нас належащия44 на нас скорби и печали в сей временней жизни, не лишены же сотвори ны Твоим всесильным ходатайством и вечныя нескончаемыя радости во Царствии Сына Твоего и Бога нашего, Емуже подобает всякая слава, честь и поклонение, со Безначальным Его Отцем, и со Пресвятым и Благим и Животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0104", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всеблаженной»"},
  {"id": "cu-mol-0105", "section": "service", "who": "rubric", "text": "(14 сентября)"},
  {"id": "cu-mol-0106", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышних сил, Небесе и земли Царице, града и страны нашея всемощная Заступнице! Приими хвалебное пение сие от нас недостойных раб Твоих, и вознеси молитвы наша ко престолу Бога Сына Твоего, да милостив будет неправдам нашим и пробавит45 благодать Свою чтущим всечестное имя Твое и с верою и любовию покланяющимся пречистому образу Твоему."},
  {"id": "cu-mol-0107", "section": "service", "who": "reader", "text": "Несмы46 бо достойни от Него помиловани быти, аще не Ты умилостивиши Его о нас, Владычице, яко вся Тебе от Него возможна суть47. Сего ради к Тебе прибегаем, яко к несомненней и скорей Заступнице нашей: услыши нас молящихся Тебе, удиви48 над нами великия и богатыя милости Твоя, яви нам небесную помощь Твою и заступление, и испроси у Бога Сына Твоего, пастырем нашим ревность и бдение о душах, градоправителем мудрость и силу, судиям правду и нелицеприятие, наставником разум и смиренномудрие, супругом любовь и согласие, чадом послушание, обидимым терпение, обидящим страх Божий, скорбящим благодушие, радующимся воздержание; нам же всем низпосли дух разума и благочестия, дух милосердия и кротости, дух чистоты и правды."},
  {"id": "cu-mol-0108", "section": "service", "who": "reader", "text": "Ей, Госпоже Пречистая! Умилосердися на немощныя люди Твоя, рассеянныя собери, заблуждшия на путь правый настави, недугующия уврачуй, старость поддержи, юныя уцеломудри, младенцы воспитай, и призри на всех нас призрением милостиваго Твоего заступления, воздвигни нас из глубины греховныя и просвети сердечныя очи наши ко зрению спасения. Милостива нам буди зде и на страшнем суде Сына Твоего, преставльшияся же в вере и покаянии от жития сего отцы и братию нашу в вечней жизни со ангелы и со всеми святыми жити сотвори."},
  {"id": "cu-mol-0109", "section": "service", "who": "reader", "text": "Ты бо еси, Госпоже, слава небесных и упование земных, Ты по Бозе наша Надежда и Заступница всех притекающих к Тебе с верою. Тебе убо молимся, и Тебе, яко всемогущей Помощнице, сами себе и друг друга и всю жизнь нашу предаем, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0110", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всецарица»"},
  {"id": "cu-mol-0111", "section": "service", "who": "rubric", "text": "(31 августа)"},
  {"id": "cu-mol-0112", "section": "service", "who": "rubric", "text": "О Пречистая Богомати, Всецарице! Услыши многоболезненное воздыхание наше пред чудотворною иконою Твоею, из удела Афонскаго в Россию принесенною, призри на чад Твоих, неисцельными недуги страждущих, ко святому Образу Твоему с верою припадающих!"},
  {"id": "cu-mol-0113", "section": "service", "who": "reader", "text": "Якоже птица крилома покрывает птенцы своя, тако и Ты ныне, присно жива сущи, покрый нас многоцелебным Твоим омофором. Тамо, идеже надежда исчезает, несумненною Надеждою буди. Тамо, идеже лютыя скорби превозмогают, терпением и ослабою явися. Тамо, идеже мрак отчаяния в души вселися, да возсияет неизреченный свет Божества!"},
  {"id": "cu-mol-0114", "section": "service", "who": "reader", "text": "Малодушныя утеши, немощныя укрепи, ожесточенным сердцам умягчение и просвещение даруй. Исцели болящия люди Твоя, о Всемилостивая Царице!"},
  {"id": "cu-mol-0115", "section": "service", "who": "reader", "text": "Ум и руки врачующих нас благослови, да послужат орудием Всемощнаго Врача, Христа Спаса нашего. Яко живей Ти сущей с нами, молимся пред иконою Твоею, о Владычице!"},
  {"id": "cu-mol-0116", "section": "service", "who": "reader", "text": "Простри руце Твои, исполненныя исцеления и врачбы, радосте скорбящих, в печалех утешение, да чудотворную помощь скоро получивше, прославляем Живоначальную и Нераздельную Троицу, Отца, и Сына, и Святаго Духа, во веки веков. Аминь."},
  {"id": "cu-mol-0117", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «В скорбех и печалех Утешение»"},
  {"id": "cu-mol-0118", "section": "service", "who": "rubric", "text": "(2 декабря)"},
  {"id": "cu-mol-0119", "section": "service", "who": "rubric", "text": "К кому возопию, Владычице? К кому прибегну в горести моей, аще не к Тебе, Царице Небесная? Кто плач мой и воздыхание мое приимет, аще не Ты, Пренепорочная, Надеждо христиан и Прибежище нам, грешным? Кто паче49 Тебе в напастех защитит?"},
  {"id": "cu-mol-0120", "section": "service", "who": "reader", "text": "Услыши убо стенание мое и приклони ухо Твое ко мне, Владычице Мати Бога моего, и не презри мене, требующаго50 Твоея помощи, и не отрини мене, грешнаго. Вразуми и научи мя, Царице Небесная; не отступи от мене, раба Твоего, Владычице, за роптание мое, но буди мне Мати и Заступница."},
  {"id": "cu-mol-0121", "section": "service", "who": "reader", "text": "Вручаю себе милостивому покрову Твоему: приведи мя, грешнаго, к тихой и безмятежной жизни, да плачуся о гресех моих. К кому бо прибегну повинный аз, аще не к Тебе, упованию и прибежищу грешных, надеждою на неизреченную милость Твою и щедроты Твоя окриляемь?"},
  {"id": "cu-mol-0122", "section": "service", "who": "reader", "text": "О Владычице, Царице Небесная! Ты мне упование и прибежище, покров и заступление и помощь. Царице моя Преблагая и скорая Заступнице, покрый Твоим ходатайством моя прегрешения, защити мене от враг видимых и невидимых; умягчи сердца злых человек, возстающих на мя."},
  {"id": "cu-mol-0123", "section": "service", "who": "reader", "text": "О Мати Господа моего Творца! Ты еси корень девства и неувядаемый цвет чистоты."},
  {"id": "cu-mol-0124", "section": "service", "who": "reader", "text": "О Богородительнице! Ты подаждь ми помощь немощствующему плотскими страстьми и болезнующему сердцем, едино бо Твое и с Тобою Твоего Сына и Бога нашего имам заступление; и Твоим пречудным заступлением да избавлюся от всякия беды и напасти, о, Пренепорочная и Преславная Божия Мати Марие. Темже со упованием глаголю и вопию: радуйся, Благодатная, радуйся, Обрадованная, радуйся, Преблагословенная, Господь с Тобою! Аминь."},
  {"id": "cu-mol-0125", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Грузинской» (Красногорской)»"},
  {"id": "cu-mol-0126", "section": "service", "who": "rubric", "text": "(4 сентября)"},
  {"id": "cu-mol-0127", "section": "service", "who": "rubric", "text": "Приими, Всеблагомощная51 Пречистая Госпоже, Владычице Богородительнице, сия честныя52 дары от нас, недостойных рабов Твоих, к Твоему цельбоносному образу пение возсылающих со умилением, яко Тебе Самой сущей ту и послушающей моления наша, подающи с верою просящим по коемуждо53 прошению исполнение: скорбящим скорби облегчаеши, немощным здравие даруеши, разслабленных и недужных исцеляеши, и от бесных бесы прогоняеши, обидимыя от обид избавляеши, и насилуемых спасаеши, грешных прощаеши, прокаженных очищаеши, и малых детей милуеши, и неплодныя от неплодства разрешаеши."},
  {"id": "cu-mol-0128", "section": "service", "who": "reader", "text": "Еще, Госпоже Владычице, от уз и темниц свобождаеши, и всякия многоразличныя страсти исцеляеши, и очныя болезни54 уврачуеши, и от смертоносныя язвы избавляеши: вся бо возможна суть ходатайством Твоим к Сыну Твоему, Христу Богу нашему."},
  {"id": "cu-mol-0129", "section": "service", "who": "reader", "text": "О Всепетая55 Мати, Пречистая Богородице! Не престай молити о нас, недостойных рабех Твоих, славящих Тя и почитающих, и покланяющихся пречистому образу Твоему, и надежду имущих невозвратну56 и веру несумненну к Тебе, Приснодеве, Преславней и Непорочней, славящих, и чтущих, и поющих Тя во веки веков. Аминь."},
  {"id": "cu-mol-0130", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Державной»"},
  {"id": "cu-mol-0131", "section": "service", "who": "rubric", "text": "(15 марта)"},
  {"id": "cu-mol-0132", "section": "service", "who": "rubric", "text": "О мира Заступнице, Мати Всепетая! Со страхом, верою и любовию припадающе пред честною иконою Твоею Державною, усердно молим Тя: не отврати лица Твоего от прибегающих к Тебе. Умоли, милосердая Мати Света, Сына Твоего и Бога нашего, сладчайшаго57 Господа Иисуса Христа: да сохранит в мире страну нашу, да утвердит державу нашу во благоденствии и избавит нас от междоусобныя брани; да укрепит Святую Церковь нашу Православную и незыблему соблюдет ю58 от неверия, раскола и ересей."},
  {"id": "cu-mol-0133", "section": "service", "who": "reader", "text": "Не имамы бо иныя помощи, разве Тебе, Пречистая Дево: Ты еси всесильная христиан Заступница пред Богом, праведный гнев Его умягчающая. Избави всех, с верою Тебе молящихся, от падений греховных, от навета злых человек, от глада, скорбей и болезней."},
  {"id": "cu-mol-0134", "section": "service", "who": "reader", "text": "Даруй нам дух сокрушения, смирение сердца, чистоту помышлений, исправление греховныя жизни и оставление согрешений наших, да вси, благодарне воспевающе величия Твоя, сподобимся Небеснаго Царствия, и тамо со всеми святыми прославим пречестное и великолепое имя59 в Троице славимаго Бога, Отца, и Сына, и Святаго Духа, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0135", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Донской»"},
  {"id": "cu-mol-0136", "section": "service", "who": "rubric", "text": "(1 сентября)"},
  {"id": "cu-mol-0137", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице, Дево Богородице, Заступнице наша благая и скорая! Воспеваем Ти вси благодарственная за чудная дела Твоя. Песнословим от лет древних неотъемлемое заступление Твое граду Москве и стране нашей, чудотворным Образом Твоим Донским всегда являемое: в бегство обращаются полки чуждих, грады и веси невредими сохраняются, людие же от лютыя смерти избавляются. Осушаются очи слезящия, умолкают стенания верных, плач в радость общую претворяется60."},
  {"id": "cu-mol-0138", "section": "service", "who": "reader", "text": "Буди и нам, Пречистая Богородице, утешение в бедствиих, возрождение надежды, образ мужества, источник милости, и в скорбных обстояниих61 неистощимое терпение нам даруй. Подаждь коемуждо по прошению и по нужде его: младенцы воспитай, юныя уцеломудри и страху Божию научи, унывающия ободри и немощную старость поддержи."},
  {"id": "cu-mol-0139", "section": "service", "who": "reader", "text": "Посети в болезнех и печалех сущия, злая сердца умягчи, братолюбие укрепи, мира и любве всех нас исполни. Примири, благосердая Мати, враждующия и оправдай оклеветанныя. Истреби пороки, да не восходят грехи наша пред Судиею всяческих62, да не постигнет нас праведный гнев Божий. Твоими молитвами, всемощным Твоим покровом огради нас от нашествий вражиих, от глада, губительства, огня, меча и всякаго инаго злострадания."},
  {"id": "cu-mol-0140", "section": "service", "who": "reader", "text": "Уповаем молитвами Твоими получити от Всевышняго Бога грехов прощение и изглаждение63 и с Богом примирение. Умоли стяжати нам Царствие Небесное и по скончании жизни нашея одесную Престола Божия стати, идеже Ты, о Всепетая Дево, Святей Троице в вечней славе предстоиши. Удостой и нас с лики Ангел и святых тамо восхвалити пречестное имя Сына Твоего со Безначальным Его Отцем и Всесвятым и Благим и Животворящим Его Духом во веки веков. Аминь."},
  {"id": "cu-mol-0141", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Елецкой-Черниговской»"},
  {"id": "cu-mol-0142", "section": "service", "who": "rubric", "text": "(18 февраля)"},
  {"id": "cu-mol-0143", "section": "service", "who": "rubric", "text": "Премилосердая наша Заступнице, и душ наших благая Хранительнице, и телес наших милосердая Целительнице, Богородице Дево!"},
  {"id": "cu-mol-0144", "section": "service", "who": "reader", "text": "Вемы64, яко недостойни есмы, не точию65 Твоих дарований причастницы быти, но и очей своих на чудотворный Твой образ возвести, зане66 души наша грехов исполнены суть и очи завистными и блудными воззреньми осквернени суть."},
  {"id": "cu-mol-0145", "section": "service", "who": "reader", "text": "Обаче67 Твое сострадание человеком, в нуждах и скорбех пребывающим, воспоминающе, им же Твоего Божественнаго Сына на первое чудо в Кане Галилейстей преклонила еси, и даже до днесь Того праведный гнев от грешников отвращаеши, паки и паки на мольбу Тебе, пред чудотворным Твоим образом, подвизаемся и со смиренным упованием Тебе просим: испроси грехом нашим прощение, от пагубных страстей исцеление, от нечувствия и от сна духовнаго пробуждение и о добродетелех христианских ревность."},
  {"id": "cu-mol-0146", "section": "service", "who": "reader", "text": "Сими убо дарованьми души наша украсивши, избави нас от горестей, в уныние некрепкая сердца наша повергающих, исцели болезни молящихся и о нихже молитву тии приносят, от напрасныя смерти жизнь нашу сохрани и сию христианскою кончиною во время подобно увенчати сподоби."},
  {"id": "cu-mol-0147", "section": "service", "who": "reader", "text": "Но и земное наше пребывание от взаимныя злобы и зависти огради, и в любви Христовой сие препровождати нам помози. Церковь Сына Твоего во всей вселенней умножи и утверди, еретиком обращение ко истине испроси, языком68 же неверным веры истинное познание. Такожде и одоление на враги и супостаты даруй, и всех нас научи, якоже во дни веселия, тако и во дни печали Тебе прославляти и о всех Сына Твоего благодарити, житие свое в Его святую волю вручати со упованием вечнаго спасения ожидати, да и тамо прославим Его Пресвятое имя и Твое милосердое предстательство во веки веков. Аминь."},
  {"id": "cu-mol-0148", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Живоносный источник»"},
  {"id": "cu-mol-0149", "section": "service", "who": "rubric", "text": "(пятница Светлой седмицы)"},
  {"id": "cu-mol-0150", "section": "service", "who": "rubric", "text": "Царице моя преблагая, надеждо моя Богородице, прибежище сирых69 и странных70 Предстательнице, скорбящих радосте, обидимых Покровительнице!"},
  {"id": "cu-mol-0151", "section": "service", "who": "reader", "text": "Зриши мою беду, зриши мою скорбь: помози ми яко немощну, окорми71 мя яко странна."},
  {"id": "cu-mol-0152", "section": "service", "who": "reader", "text": "Обиду мою веси, разреши ту, яко волиши72: яко не имам иныя помощи разве Тебе, ни иныя предстательницы, ни благия утешительницы, токмо Тебе, о Богомати, яко да сохраниши мя и покрыеши во веки веков. Аминь."},
  {"id": "cu-mol-0153", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Жировицкой»"},
  {"id": "cu-mol-0154", "section": "service", "who": "rubric", "text": "(20 мая)"},
  {"id": "cu-mol-0155", "section": "service", "who": "rubric", "text": "О Премилосердная Госпоже, Дево Богородице! Киима73 устнама прикоснуся ко святыни Твоей, или киими словесы исповем щедроты Твоя, людем являемыя: никтоже бо, притекаяй к Тебе, отходит тощ и не услышан."},
  {"id": "cu-mol-0156", "section": "service", "who": "reader", "text": "От юности моея взысках помощи и заступления Твоего, и николиже74 лишен бых милосердия Твоего. Зриши, Госпоже, скорби сердца моего и язвы души моея веси."},
  {"id": "cu-mol-0157", "section": "service", "who": "reader", "text": "И ныне, коленопреклоненно предстоя пред пречистым Твоим образом, моления моя приношу Ти. Не лиши мя всесильнаго ходатайства Твоего в день скорби моея, и в день печали моея заступи мя. Тока слез моих не отвратися, Владычице, и радости мое сердце исполни. Прибежище и предстательство буди мне, Милостивая, и света Твоего зарями ум мой просвети."},
  {"id": "cu-mol-0158", "section": "service", "who": "reader", "text": "И не токмо о себе молю Тя, но и о людех, притекающих к заступлению Твоему. Церковь Сына Твоего по благости соблюди, и огради ю от злокозненных наветов враг, возстающих на ню. Архипастырем нашим посли помощь Твою во апостольстве, и сохрани их здравы, долгоденствующи, право правящи слово истины Господни. Пастырем испроси у Бога, Сына Твоего, ревность и бдение о душах врученнаго им стада словеснаго, и дух разума и благочестия, чистоты и правды Божественныя им низпосли."},
  {"id": "cu-mol-0159", "section": "service", "who": "reader", "text": "Испроси такожде, Владычице, у Господа власть предержащим и градоправителем мудрость и силу, судиям правду и нелицеприятие, всем же притекающим к Тебе дух целомудрия, смиренномудрия, терпения и любве."},
  {"id": "cu-mol-0160", "section": "service", "who": "reader", "text": "Еще же молю Тя, Премилосердная, осени страну нашу кровом Твоея благостыни, и избави ю от бедствий стихийных, нашествия иноплеменников и междоусобных нестроений, да вси, живущии в ней, в любве и мире пребывающе, тихое и безмятежное житие поживут, и благ вечных молитвами Твоими унаследивше, возмогут купно с Тобою восхваляти Бога на небеси во веки. Аминь."},
  {"id": "cu-mol-0161", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Абалакская»"},
  {"id": "cu-mol-0162", "section": "service", "who": "rubric", "text": "(2 августа, 10 декабря)"},
  {"id": "cu-mol-0163", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице моя Богородице, милосердия сущи источник, покрове, упование и прибежище христиан! Тебе, Всесильней Предстательнице и Споручнице покаяния и спасения моего, аз, грешный раб Твой, вручаю душу и тело мое, входы и исходы75 моя, веру и жительство мое, кончину и число дней моих, глаголы и помышления моя, дела и начинания моя."},
  {"id": "cu-mol-0164", "section": "service", "who": "reader", "text": "Ты же, милостивая Мати Божия, мною руководствуй, покрывай, соблюдай и спасай мя от всех вражеских козней невредимо, да немолчно, до последняго издыхания моего, взываю Ти: Радуйся, Невесто неневестная! Радуйся, Святая, святых большая! Пресвятая Богородице, спаси мя! Аминь!"},
  {"id": "cu-mol-0165", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Корчемная»"},
  {"id": "cu-mol-0166", "section": "service", "who": "rubric", "text": "(10 декабря)"},
  {"id": "cu-mol-0167", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Небеснаго Царя Мати, Богоизбранная Отроковице! Ненадежных надеяние, больных исцеление, сирым предстательнице, скорбящим утешение и радость, обидимым покровительнице и всем в бедах и напастях сущим скорое поможение и заступление!"},
  {"id": "cu-mol-0168", "section": "service", "who": "reader", "text": "Помози, о Мати Божия, и нам грешным в скорби нашей, возвесели радостию сердца людей Твоих; управи в мире и тишине жизнь нашу и не даждь во отчаяние впасти. Ты бо Едина еси паче всех святых и паче всех Горних умов Предстательница наша к Богу, яко Всеблагаго Царя Благая Мати."},
  {"id": "cu-mol-0169", "section": "service", "who": "reader", "text": "Темже мы, грешнии, на Пречистый Твой образ Знамения взирающе, умиленно преклоняем колена и, благоговейно лобызающе, молим Тя, Благосердая Мати: не отрини смиреннаго моления нашего и яви нам знамение милости Твоея: никтоже бо, к Тебе прибегая со упованием, исходит от Тебе посрамлен, но просит благодати и приемлет дар к полезному прошению, прославляя Сына Твоего и Бога, и Тебе с Ним, во веки веков. Аминь."},
  {"id": "cu-mol-0170", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Курская-Коренная»"},
  {"id": "cu-mol-0171", "section": "service", "who": "rubric", "text": "(10 декабря, 21 марта, 21 сентября)"},
  {"id": "cu-mol-0172", "section": "service", "who": "rubric", "text": "О Царице Небесная! Кто изочтет великое множество чудес Твоих, кто исчислит вопли молитвенных прошений, токи умиленных слез, благодарных воздыханий, пролитых пред иконою Твоею."},
  {"id": "cu-mol-0173", "section": "service", "who": "reader", "text": "Овеяна убо вся она скорбию народною, плачем угнетенных и радостною хвалою утешенных. Припадаху к ней людие, понесшие агарянское иго, плакаху Москва в смутное время, взываше Курск в нашествие вражеское. Вопияше вся область во дни смертоносных болезней и бед, и вся скорби на радость прелагала еси."},
  {"id": "cu-mol-0174", "section": "service", "who": "reader", "text": "Темже и ныне благослови землю Русскую. Спаси от греха, погибели и соблазнов страну нашу. Излей благодать на труд земледельческий и на всякое благое начинание общественное. Помяни, Пресвятая Дево, по имени всех предстоящих и молящихся и вся люди, требующия Твоего утешения, помощи и милосердия."},
  {"id": "cu-mol-0175", "section": "service", "who": "reader", "text": "Ты убо веси тайная сердец наших. Темже всем по потребе их прошения исполни. Изряднее же заблуждших обрати к покаянию, нас же всех умудри светом Евангельския любви и добрых дел. Архипастыри и пастыри и вся верныя в Православии до смерти тверды покажи, в Царство Небесное управи и со Христом жити сотвори во веки веков. Аминь."},
  {"id": "cu-mol-0176", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Новгородская»"},
  {"id": "cu-mol-0177", "section": "service", "who": "rubric", "text": "(10 декабря)"},
  {"id": "cu-mol-0178", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и поклоняемся Тебе пред святою чудотворною иконою Твоею, воспоминающе дивное знамение Твоего заступления, великому Новуграду от нея явленное во дни ратнаго на сей град нашествия."},
  {"id": "cu-mol-0179", "section": "service", "who": "reader", "text": "Смиренно молим Тя, Всесильная рода нашего Заступнице: якоже древле отцем нашим на помощь ускорила еси, тако и ныне нас, немощных и грешных, сподоби Твоего Матерняго заступления и благопопечения."},
  {"id": "cu-mol-0180", "section": "service", "who": "reader", "text": "Спаси и сохрани, Владычице, под кровом милости Твоея Церковь Святую, град Твой, всю страну нашу православную и всех нас, припадающих к Тебе с верою и любовию умиленно просящих со слезами Твоего заступления."},
  {"id": "cu-mol-0181", "section": "service", "who": "reader", "text": "Ей, Госпоже Всемилостивая! Умилосердися на ны, обуреваемыя грехи многими, простри ко Христу Господу Богоприимныя руце Твоя и предстательствуй за нас пред благостию Его, просящи нам прощения прегрешений наших, благочестнаго мирнаго жития, благия христианския кончины и добраго ответа на Страшнем Суде Его, да, спасаеми всесильными Твоими к Нему молитвами, блаженство райское унаследуем и со всеми святыми воспоем Пречестное и Великолепое имя Достопоклоняемыя Троицы, Отца и Сына и Святаго Духа, и Твое велие к нам милосердие во веки веков. Аминь."},
  {"id": "cu-mol-0182", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Иверской»"},
  {"id": "cu-mol-0183", "section": "service", "who": "rubric", "text": "(26 октября, 25 февраля и во вторник Светлой седмицы)"},
  {"id": "cu-mol-0184", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа, Царице Небесе и земли! Вонми многоболезненному воздыханию душ наших, призри с высоты святыя Твоея на нас, с верою и любовию покланяющихся пречистому образу Твоему."},
  {"id": "cu-mol-0185", "section": "service", "who": "reader", "text": "Се бо грехми погружаемии и скорбьми обуреваемии, взирающе на Твой образ, яко живей Ти сущей с нами, приносим смиренная моления наша. Не имамы бо ни иныя помощи, ни иного предстательства, ни утешения, токмо Тебе, о Мати всех скорбящих и обремененных!"},
  {"id": "cu-mol-0186", "section": "service", "who": "reader", "text": "Помози нам, немощным, утоли скорбь нашу, настави на путь правый нас, заблуждающих, уврачуй болезненная сердца наша и спаси безнадежных, даруй нам прочее время живота нашего в мире и тишине проводити, подаждь христианскую кончину и на Страшнем Суде Сына Твоего явися нам милосердая Предстательница, да всегда поем, величаем и славим Тя яко благую Заступницу рода христианскаго, со всеми угодившими Богу. Аминь."},
  {"id": "cu-mol-0187", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Иерусалимской»"},
  {"id": "cu-mol-0188", "section": "service", "who": "rubric", "text": "(25 октября)"},
  {"id": "cu-mol-0189", "section": "service", "who": "rubric", "text": "Пресвятая Госпоже, Владычице Богородице, упование всех уповающих на Тя, Заступнице печальных, прибежище отчаянных, вдов и сирот Питательнице!"},
  {"id": "cu-mol-0190", "section": "service", "who": "reader", "text": "Услыши и помилуй ны, грешныя и недостойныя рабы Своя, со умилением ко пречистому Твоему образу припадающия: умоли, Милосердая Владычице, Сына Твоего и Господа нашего Иисуса Христа, да отвратит от нас праведный гнев Свой, да простит грехи и беззакония наша, яко да сподобимся благостию Его скончати житие наше в покаянии и получити милость Его со всеми избранными Его, яко благословена и препрославлена еси во веки веков. Аминь."},
  {"id": "cu-mol-0191", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Избавительница»"},
  {"id": "cu-mol-0192", "section": "service", "who": "rubric", "text": "(30 октября, 30 апреля)"},
  {"id": "cu-mol-0193", "section": "service", "who": "rubric", "text": "О, Мати Божия, помоще и защита наша, егда попросим, буди избавительнице наша, на Тя бо уповаем и всегда вседушно Тя призываем: умилосердися и помози, пожалей и избави, приклони ухо Твое и наши скорбныя и слезныя молитвы приими, и якоже хощеши, успокой и обрадуй нас, любящих твоего Безначального Сына и Бога нашего. Аминь."},
  {"id": "cu-mol-0194", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Избавление от бед страждущих»"},
  {"id": "cu-mol-0195", "section": "service", "who": "rubric", "text": "(30 июня)"},
  {"id": "cu-mol-0196", "section": "service", "who": "reader", "text": "Мати Божия, помоще и защито! Егда потребуем, буди Избавлением нам, страждущим и погибающим от лютых бед, на Тя бо уповаем и всегда вседушно Тебе призываем: умилосердися и помози, пожалей и избави от бед страждущих и погибающих нас, от лютых сетей лукаваго исхити, приклони ухо Твое, и наши слезныя, скорбныя молитвы приими и, якоже хощеши, упокой и обрадуй нас."},
  {"id": "cu-mol-0197", "section": "service", "who": "reader", "text": "Научи послушание Господу Богу приносити, всем сердцем, всею душею, всем естеством Сына Твоего возлюбити, плоды трудов достойны Ему приносити. Умири сердца наша, да в едином Духе и всеми делами нашими прославим Безначальнаго Отца со Единородным Его Сыном и с Пресвятым Благим и Животворящим Его Духом, и Твое милостивное Матернее предстательство, ныне, и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0198", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Казанской»"},
  {"id": "cu-mol-0199", "section": "service", "who": "rubric", "text": "(4 ноября и 21 июля)"},
  {"id": "cu-mol-0200", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Со страхом, верою и любовию пред честною (и чудотворною) иконою Твоею припадающе, молим Тя: не отврати лица Твоего от прибегающих к Тебе."},
  {"id": "cu-mol-0201", "section": "service", "who": "reader", "text": "Умоли, милосердая Мати, Сына Твоего и Бога нашего, Господа Иисуса Христа, да сохранит мирну страну нашу, Церковь же Свою Святую непоколебиму да соблюдет и от неверия, ересей и раскола да избавит."},
  {"id": "cu-mol-0202", "section": "service", "who": "reader", "text": "Не имамы бо иныя помощи, не имамы иныя надежды, разве Тебе, Пречистая Дево: Ты еси всесильная христиан Помощница и Заступница. Избави же и всех, с верою Тебе молящихся, от падений греховных, от навета злых человек, от всяких искушений, скорбей, болезней, бед и от внезапныя смерти."},
  {"id": "cu-mol-0203", "section": "service", "who": "reader", "text": "Даруй нам дух сокрушения, смирение сердца, чистоту помышлений, исправление греховныя жизни и оставление прегрешений, да вси, благодарне воспевающе величия и милости Твоя, являемыя над нами зде на земли, сподобимся и Небеснаго Царствия, и тамо со всеми святыми прославим пречестное и великолепое имя Отца, и Сына, и Святаго Духа во веки веков. Аминь."},
  {"id": "cu-mol-0204", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Калужской»"},
  {"id": "cu-mol-0205", "section": "service", "who": "rubric", "text": "(25 октября, 31 июля, 15 сентября)"},
  {"id": "cu-mol-0206", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Христа Бога нашего, Дивная Царице Небесе и земли! Вонми многоболезненному воздыханию сердец наших; призри с высоты святыя Твоея на нас, с верою и любовию предстоящих пред чудотворною Твоею иконою и со умилением молящихся Тебе, Владычице!"},
  {"id": "cu-mol-0207", "section": "service", "who": "reader", "text": "Не предаждь умалению Церковь Православную, помози нам, Пресвятая Богородице, святоотеческую Православную веру до конца дней наших непорочно сохранити, во всех заповедех Господних неуклонно ходити и избави ны от пагубных душевредных учений. На Твою, Дивная Царице Небесе и земли, милость уповаем, раби Твои: очисти умы наша от греховных помыслов, душевнаго разслабления, обуревания страстей, от искушений, соблазнов и грехопадений; Ты бо еси, Владычице, крепкое прибежище грешников кающихся."},
  {"id": "cu-mol-0208", "section": "service", "who": "reader", "text": "Воздвигни нас из глубины греховныя и истинным покаянием ороси изсохшая сердца наша, просвети сердечная очеса наша ко зрению спасения, и прельщенных бесовскою прелестию на путь правый настави; всякое дело злое и богопротивное разруши; всякому же благому и богоугодному делу научи и споспешествуй; вложи, Владычице, в сердца наша дух страха Божия, дух благочестия, дух кротости, смирения, терпения, незлобия; умягчи злая сердца наша и ниспосли нам ревность о спасении ближних наших."},
  {"id": "cu-mol-0209", "section": "service", "who": "reader", "text": "Вразуми и научи ны, о Всемилостивая Заступнице наша, како безгрешно ходити по пути земнаго сего жития: яко Ты, Пресвятая, веси веру нашу, и упование наше видиши."},
  {"id": "cu-mol-0210", "section": "service", "who": "reader", "text": "О Владычице мира! Скорбящих утеши, бедствующим помози; сохрани от молниеноснаго грома, тлетворных ветр, лютых болезней, смертоносныя язвы, междоусобныя брани, нашествия врагов иноплеменных."},
  {"id": "cu-mol-0211", "section": "service", "who": "reader", "text": "О Пресвятая Богородице! Избави ны от внезапныя и насильственныя смерти; всем нам даруй обращение на путь истинный и христианскую кончину живота нашего безболезненну, непостыдну, мирну, Святых Тайн причастну."},
  {"id": "cu-mol-0212", "section": "service", "who": "reader", "text": "Во время исхода нашего предстани нам, Дево Богородице, и избави ны от власти бесовския, воздушных горьких мытарств и огня вечнаго. Скончавшимся внезапною смертию милостива быти Сына Твоего умоли, и о всех усопших, иже не имут сродников, о упокоении их Сына Твоего умоляющих, Сама буди непрестанная и теплая Молитвенница и Ходатаица."},
  {"id": "cu-mol-0213", "section": "service", "who": "reader", "text": "Преставльшихся же в вере и покаянии от временнаго жития сего отцы, братию, матери и сестры наша сподоби Твоим ходатайством вселитися во обителех Небесных со Ангелы и со всеми святыми, идеже непрестанно гласы празднующих и радостно славящих Пресвятую Троицу, Отца, и Сына, и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0214", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Киево-Братской»"},
  {"id": "cu-mol-0215", "section": "service", "who": "rubric", "text": "(23 мая, 15 июня, 19 сентября)"},
  {"id": "cu-mol-0216", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Пречистая Владычице Богородице. Призри Всемилостивым Твоим оком на нас, предстоящих пред пречистым Твоим образом, Киево-Братским нарицающимся, и молящихся Ти пред ним."},
  {"id": "cu-mol-0217", "section": "service", "who": "reader", "text": "Да возсияет неизреченный свет Возлюбленнаго Сына Твоего, Господа нашего Иисуса Христа в сердцах наших. Да будет воля Его чрез все житие наше. Да дарует нам прощение и очищение всех грехов и прегрешений наших."},
  {"id": "cu-mol-0218", "section": "service", "who": "reader", "text": "Не имамы иныя помощи, ни иныя надежды, токмо Тебе, Пречистая."},
  {"id": "cu-mol-0219", "section": "service", "who": "reader", "text": "Якоже в древния времена град Вышгород и землю Киевскую прославила еси знамениями и чудесы от иконы Твоея чудныя, егда иновернаго агарянина чудным образом от воднаго потопления в реце Днепре спасла еси, и до обители Киево-Братския неврежденна доставила еси, и тамо истинное покаяние его прияла еси, и светом святаго крещения просветив, во Ангельский чин в сей обители облекла еси, и тем ко спасению и истинныя веры православныя утверждению путеводила еси."},
  {"id": "cu-mol-0220", "section": "service", "who": "reader", "text": "Сего ради и мы, грешнии и недостойнии, дерзающе просим и молим: не отрини нас, молящихся Ти, пред сею дивною и чудотворною иконою Твоею. Укрепи веру в нас правую, даруй любовь друг ко другу нелицемерную. Буди Взбранной Воеводой на вся видимая и невидимая враги наша: неверных к правоверию обрати, верных же на путь покаяния и спасения настави."},
  {"id": "cu-mol-0221", "section": "service", "who": "reader", "text": "Помози, Госпоже Владычице, воздвигнути храм и обитель дивному и славному, достопоклоняемому Ангелы и человеки, имене Твоему, в честь и память чудотворнаго образа Твоего Киево-Братскаго."},
  {"id": "cu-mol-0222", "section": "service", "who": "reader", "text": "Да и в храме сем и обители сей, паче же в душах и сердцах наших, прославим Тя, Ходатаицу и Молитвенницу за род наш, и Тобою славу возслем Отцу, и Сыну, и Святому Духу, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0223", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Коневской»"},
  {"id": "cu-mol-0224", "section": "service", "who": "rubric", "text": "(23 июля)"},
  {"id": "cu-mol-0225", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Дево Богородице! Вонми смиренному молению моему, и сокрушенно ныне предстоящаго образу Твоему услыши глас."},
  {"id": "cu-mol-0226", "section": "service", "who": "reader", "text": "Вем бо, о Содетеля моего Мати, яко Ты предстательство христиан непостыдное и ходатайство ко Творцу непреложное. Вем и сие, яко беззакония моя превзыдоша главу мою, и яко бремя тяжкое отяготеша на мне, и уже несмь достоин видети высоту Небесную, ниже воззрети ко Престолу славы Сына Твоего и Бога нашего, но достоин мук и вечнаго осуждения."},
  {"id": "cu-mol-0227", "section": "service", "who": "reader", "text": "Сего ради к Тебе (со предстоящими купно) припадаю, Тя прошу умиленно, к Тебе со слезами взываю: сотвори к Нему матернее Твое моление, да не отвержет нас, грешных от лица Своего: но яко Милостив, да простит нам согрешения наша вольная и невольная, на путь спасения наставляя нас, и свыше силою укрепляя к творению заповедей Своих святых."},
  {"id": "cu-mol-0228", "section": "service", "who": "reader", "text": "Да сохранит нас от соблазнов мира, от вожделений греховных, от козней диавольских, и от нападения видимых врагов. Да благословит дела рук наших, подавая обители сей и всякому граду и стране обилие благ земных. Да сотворит нам дни благи и безмятежны, да оградит миром Церковь Свою святую, и разстоящая да соединит той, яко благ Господь, Долготерпелив и Многомилостив, от всея твари со Отцем и Святым Духом славимый во веки веков. Аминь."},
  {"id": "cu-mol-0229", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Купятицкой»"},
  {"id": "cu-mol-0230", "section": "service", "who": "rubric", "text": "(28 ноября)"},
  {"id": "cu-mol-0231", "section": "service", "who": "rubric", "text": "О Преблагословенная Владычице, всемощная Заступнице, непостыдное наше Упование! Приими хвалебное и благодарственное пение нас, недостойных раб Твоих, и вознеси молитвы наша ко Престолу Сына и Бога Твоего, да милостив будет неправдам нашим, пробавит благость Свою чтущим Всечестное имя Твое и с верою и любовию поклоняющимся чудотворному образу Твоему."},
  {"id": "cu-mol-0232", "section": "service", "who": "reader", "text": "Сохрани землю нашу от всякия беды, посли мир людем на земли, собери вся христианы во едино стадо право славящих Бога в Троице Единаго. Утверди нас всех в Вере Христове и в усердии к Церкве Православней. Вложи в сердца наша дух страха Божия, благочестия и смирения. В напастех терпение нам подаждь, во благоденствии воздержание, к ближним любовь, ко врагам всепрощение, в добрых делех преуспеяние. Избави нас от всякаго искушения и от окамененнаго нечувствия."},
  {"id": "cu-mol-0233", "section": "service", "who": "reader", "text": "В страшный день Суда сподоби нас ходатайством Твоим стати одесную Сына Твоего Христа Бога нашего. Емуже подобает всякая слава, честь и поклонение со Отцем и Святым Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0234", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Любечской»"},
  {"id": "cu-mol-0235", "section": "service", "who": "rubric", "text": "(20 мая)"},
  {"id": "cu-mol-0236", "section": "service", "who": "rubric", "text": "О, Пресвятая и Преблагословенная Мати Господа и Спаса нашего Иисуса Христа, Пречистая Приснодево, Богородице Марие! Припадаем и покланяемся Тебе пред святою и чудотворною иконою Твоею, юже от лет древних зде чудесы многими и исцеленьми неисчетными прославити благоизволила еси."},
  {"id": "cu-mol-0237", "section": "service", "who": "reader", "text": "Смиренно молимся Тебе, Благой и Милосердной Заступнице нашей, предстательством угодника Твоего, преподобнаго Антония Печерскаго, вонми гласу грешных молений наших, не презри воздыханий от души, виждь скорби и беды, нас обышедшия, и, яко любвеобильная воистину Мати, потщися на помощь нам, безпомощным, унылым, во многия и тяжкия грехи впадшим и присно прогневляющим Господа и Создателя нашего, Егоже умоли, Предстательнице наша, да не погубит нас со беззаконии нашими, но явит нам человеколюбную Свою милость."},
  {"id": "cu-mol-0238", "section": "service", "who": "reader", "text": "Испроси нам, Владычице, у благости Его, телесное здравие и душевное спасение, благочестное и мирное житие, земли плодоносие, воздуха благорастворение, дожди благовременны и благословение свыше на вся благая дела и начинания наша. Исходатайствуй, Госпоже, у Царя царствующих и Господа господствующих стране нашей на вся враги победу и одоление, всем же православным христианом милость Божию, благоустроение и во всех благих изобилие."},
  {"id": "cu-mol-0239", "section": "service", "who": "reader", "text": "О, Царице Всепетая, Мати Божия Всеблагая, простри богоноснии руце Твои к возлюбленному Сыну Твоему и Богу нашему, умоли Его вся ны спасти и избавити погибели вечныя. Якоже древле на месте сем отцем нашим милость Твою являла еси, Владычице, сице и нам ныне яви, Богородице, Твоя щедроты: болящия исцели, скорбящия утеши, бедствующим помози."},
  {"id": "cu-mol-0240", "section": "service", "who": "reader", "text": "Споспеши всем нам носити иго Христово в терпении и смирении и сподоби нас благочестно житие сие земное скончати, христианскую непостыдную кончину получити и Небесное Царствие унаследити Матерним ходатайством Твоим к рождшемуся от Тебе Господу и Богу нашему Иисусу Христу, Емуже со Безначальным Его Отцем и Пресвятым Духом подобает всякая слава, честь и поклонение, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0241", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Максимовской»"},
  {"id": "cu-mol-0242", "section": "service", "who": "rubric", "text": "(1 мая)"},
  {"id": "cu-mol-0243", "section": "service", "who": "rubric", "text": "Нескверная, неблазная76, нетленная, Пречистая, Чистая Дево, Богоневесто Владычице, яже Бога Слова человеком преславным Твоим рождеством соединившая, и отринувшееся естество рода нашего Небесным совокупльшая, яже ненадежных едина надеждо и боримых помоще, готовое заступление к Тебе притекающих и всех христиан прибежище!"},
  {"id": "cu-mol-0244", "section": "service", "who": "reader", "text": "Не гнушайся мене грешнаго, сквернаго, скверными помыслы, и словесы, и деяньми всего себе непотребна сотворша и разумом лености сластей жития раба бывша. Но яко человеколюбиваго Бога Мати, человеколюбне умилосердися о мне, грешнем и блуднем, и приими мое еже от скверных устен приносимое Тебе моление, и Твоего Сына и нашего Владыку и Господа, Матернее Твое дерзновение употребляющи, моли, да отверзет и мне человеколюбныя утробы Своея благости, и презрев моя безчисленная прегрешения, обратит мя к покаянию и Своих заповедей делателя искусна77 явит мя."},
  {"id": "cu-mol-0245", "section": "service", "who": "reader", "text": "И предстани мне присно, яко милостивая, и милосердая, и благолюбивая в настоящем убо житии теплая78 Предстательница и Помощница, сопротивных нашествия отгоняющи, и ко спасению наставляющи мя, и во время исхода моего окаянную мою душу соблюдающи, и темныя зраки79 лукавых бесов далече от нея отгоняющи, в страшный же день Суда вечныя мя избавляющи муки, и неизреченныя славы Твоего Сына и Бога нашего наследника мя показующи: Юже и да улучу, Владычице моя, Пресвятая Богородице, Твоим ходатайством и заступлением, благодатию и человеколюбием Единороднаго Сына Твоего, Господа и Бога и Спаса нашего Иисуса Христа, Емуже подобает всякая слава, честь и поклонение, со Безначальным Его Отцем, и Пресвятым и Благим и Животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0246", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Мариупольской»"},
  {"id": "cu-mol-0247", "section": "service", "who": "rubric", "text": "(28 августа)"},
  {"id": "cu-mol-0248", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Царице небесе и земли, Преблагословенная Мати Христа Бога нашего! С верою и любовию молитвенно прибегаем мы недостойнии к Тебе, Пречистая Заступнице наша."},
  {"id": "cu-mol-0249", "section": "service", "who": "reader", "text": "Ты еси Покровительнице града нашего Мариуполя и всея Приазовския земли благословение. Твой бо образ святый, чудесно явленный некогда в каменных горах Крымских, избави люди греческия от страшных бедствий змия великаго, пожиравшаго скоты и вся окрест живущия – избави и нас от вредоносных козней диавольских, от враг видимых и невидимых, от напастей, скорбей и болезней и всякаго зла."},
  {"id": "cu-mol-0250", "section": "service", "who": "reader", "text": "Ты еси Путеводительнице благая, путь спасения верным указующая. Твой бо образ святый принесеся от гор Крымских во основание града нашего Мариуполя святителем Игнатием, и яко светильник пресветлый просвети верою православною вся живущия в нем."},
  {"id": "cu-mol-0251", "section": "service", "who": "reader", "text": "Ты еси воистину Богородице всепетая, яко вся Тебе возможна суть и елика80 аще восхощеши, власть имаши вся совершити. Никтоже бо притекаяй к Тебе, пред образом сим молящеся посрамлен отходит, но просит благодати и приемлет милость по благому изволению во спасение душ и телес."},
  {"id": "cu-mol-0252", "section": "service", "who": "reader", "text": "О Всемилостивая, Мати, Мариупольское Похвало и наше Заступление! Тебе единой от Всевышняго дадеся власть во всем заступати и спасати нас: Ты еси верное и скорое врачевство греховных страстей наших. От Тебя Господь всяко слово прошения приемлет, тебе вси ангели и архангели и вся начала смиренно служат, и яко Царицу Небесную вси восхваляют. Ты отверзла еси верным двери Царствия Небеснаго, – отверзи и нам, чрез наше искреннее покаяние двери спасения душ наших."},
  {"id": "cu-mol-0253", "section": "service", "who": "reader", "text": "Яви нам богатую помощь Твою и благопоспеши во всяком деле блазе81: от всякаго же начинания греховнаго и помышления лукаваго отврати нас, озари наш ум светом истиннаго богопознания, согрей сердце наша любовию Христовою и подаждь нам, Всеблагая, вся полезная ко спасению."},
  {"id": "cu-mol-0254", "section": "service", "who": "reader", "text": "Не престай молитися о нас, недостойных рабех Твоих, славящих Тя и почитающих Тя, и покланяющихся со умилением Пречистому образу Твоему."},
  {"id": "cu-mol-0255", "section": "service", "who": "reader", "text": "Да Твоим предстательством соблюдаеми и покровом Твоим осеняеми, прославим Господа и Спаса нашего Иисуса Христа, со Безначальным Отцем и Пресвятым и благим и животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0256", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Милостивая»"},
  {"id": "cu-mol-0257", "section": "service", "who": "rubric", "text": "(25 ноября, 8 января)"},
  {"id": "cu-mol-0258", "section": "service", "who": "reader", "text": "Испроси нам, Владычице, у благости Его, телесное здравие и душевное спасение, благочестное и мирное житие, земли плодоносие, воздуха благорастворение, дожди благовременны и благословение свыше на вся благая дела и начинания наша, и якоже древле призрела еси милостиво на смиренное славословие послушника Афонскаго, воспевавшаго Ти песнь хвалебную пред Пречистою иконою Твоею, и послала еси к нему Архангела Гавриила научити его пети песнь небесную, еюже славословят Тя ангели горе, сице приими благоутробно и наше ныне усердно приносимое Тебе молитвословие, и принеси е Сыну Твоему и Богу, да милостив будет Он нам грешным, и пробавит милость Свою всем чтущим Тя и с верою покланяющимся Святому Образу Твоему."},
  {"id": "cu-mol-0259", "section": "service", "who": "reader", "text": "О, Царице Всемилостивая, Мати Божия Всеблагая, простри к Нему Богоносныя Твои руце, имиже Его, яко младенца носила еси, и умоли Его вся ны спасти и избавити погибели вечныя. Яви нам, Владычице, Твоя щедроты: болящия исцели, скорбящия утеши, бедствующим помози: благопоспеши всем нам носити иго Христово в терпении и смирении, сподоби нас благочестно житие сие земное скончати, христианскую непостыдную кончину получити, и Небесное Царствие унаследити, Матерним ходатайством Твоим к рождшемуся от Тебе Христу Богу нашему, Емуже со Безначальным Его Отцем и Пресвятым Духом, подобает всякая слава, честь и поклонение, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0260", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Милующая», или «Достойно есть»"},
  {"id": "cu-mol-0261", "section": "service", "who": "rubric", "text": "(24 июня)"},
  {"id": "cu-mol-0262", "section": "service", "who": "rubric", "text": "О Пресвятая и Премилостивая Владычице Богородице! Припадающе ко святей иконе Твоей, смиренно молимся Тебе: вонми гласу моления нашего, виждь скорби, виждь беды наша, и яко любвеобильная Мати, потщися на помощь нам безпомощным: умоли Сына Твоего и Бога нашего, да не погубит нас за беззакония наша, но да явит нам человеколюбно Свою милость."},
  {"id": "cu-mol-0263", "section": "service", "who": "reader", "text": "Испроси нам, Владычице, у благости Его телесное здравие, и душевное спасение, и мирное житие, земли плодоносие, воздуха благорастворение, и благословение свыше на вся благая дела и начинания наша. И якоже древле призрела еси милостивно на смиренное славословие послушника Афонскаго, воспевавшаго Тя пред пречистою иконою Твоею, и Ангела к нему послала еси, да научит его воспевати песнь небесную, еюже славословят Тя Ангели, тако и ныне приими наше усердное молитвословие, Тебе приносимое."},
  {"id": "cu-mol-0264", "section": "service", "who": "reader", "text": "О Царице Всепетая! Простри ко Господу богоноснии Твои руце, имиже Богомладенца Иисуса Христа носила еси, и умоли Его избавити нас от всякаго зла. Яви, Владычице, Твою милость к нам: болящия исцели, скорбящия утеши, бедствующим помози и сподоби нас благочестно житие сие земное совершити, христианскую непостыдную кончину получити и Небесное Царствие наследити, Матерним ходатайством Твоим к рождшемуся от Тебе Христу Богу нашему, Емуже, со Безначальным Его Отцем и Пресвятым Духом, подобает всякая слава, честь и поклонение, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0265", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Млекопитательница»"},
  {"id": "cu-mol-0266", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "cu-mol-0267", "section": "service", "who": "rubric", "text": "Приими, Госпоже Богородительнице, слезная моления рабов Твоих, к Тебе притекающих. Зрим Тя на святей иконе, на руках носящую и млеком питающую Сына Твоего и Бога нашего, Господа Иисуса Христа."},
  {"id": "cu-mol-0268", "section": "service", "who": "reader", "text": "Аще и безболезненно родила еси Его, обаче Матерния скорби веси и немощи сынов и дщерей человеческих зриши. Темже тепле припадающе к цельбоносному Образу Твоему и умиленно сей лобызающе, молим Тя, Всемилостивая Владычице: нас грешных, осужденных в болезнех родити и в печалех питати чада наша, милостивно пощади и сострадательно заступи, младенцы же наша, такожде и родившия их, от тяжкаго недуга и горькия скорби избави."},
  {"id": "cu-mol-0269", "section": "service", "who": "reader", "text": "Даруй им здравие и благомощие, да и питаеми от силы в силу возрастати будут, и питающия их исполнятся радостию и утешением, яко да и ныне предстательством Твоим из уст младенцев и ссущих82 Господь совершит хвалу Свою."},
  {"id": "cu-mol-0270", "section": "service", "who": "reader", "text": "О Мати Сына Божия! Умилосердися на матери сынов человеческих и на немощныя люди Твоя: постигающия нас болезни скоро исцели, належащия на нас скорби и печали утоли, и не презри слез и воздыханий рабов Твоих. Услыши нас, в день скорби пред иконою Твоею припадающих, и в день радости и избавления приими благодарная хваления сердец наших. Вознеси мольбы наша ко Престолу Сына Твоего и Бога нашего, да милостив будет ко грехом и немощем нашим и пробавит милость Свою ведущим имя Его, яко да и мы, и чада наша прославим Тя, милосердую Заступницу и верную надежду рода нашего, во веки веков. Аминь."},
  {"id": "cu-mol-0271", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Муромской»"},
  {"id": "cu-mol-0272", "section": "service", "who": "rubric", "text": "(25 апреля)"},
  {"id": "cu-mol-0273", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышних сил, Небесе и земли Царице, града и страны нашея Всемощная Заступнице! Услыши нас, молящихся Тебе, и испроси у Бога Сына Твоего пастырем нашим ревность и бдение о душах, градоправителем – мудрость и силу, судиям – правду и нелицеприятие, наставником – разум и смиренномудрие, супругом – любовь и согласие, чадом – послушание, обидимым – терпение, обидящим — страх Божий, скорбящим – благодушие, радующимся – воздержание."},
  {"id": "cu-mol-0274", "section": "service", "who": "reader", "text": "Нам же всем низпосли дух разума и благочестия, дух милосердия и кротости, дух чистоты и правды. Ей, Госпоже Пречистая! Умилосердися на немощныя люди Твоя: разсеянныя собери, заблудшия на путь правый настави, недугующия уврачуй, старость поддержи, юныя уцеломудри, младенцы воспитай и призри на всех нас призрением милостиваго Твоего заступления."},
  {"id": "cu-mol-0275", "section": "service", "who": "reader", "text": "Милостива нам буди зде и на Страшном Суде Сына Твоего. Ты бо еси, Госпоже, слава Небесных и упование земных, ты по Бозе наша надежда и Заступница всех притекающих к Тебе с верою. Тебе убо молимся и Тебе, яко всемогущей Помощнице, сами себе и друг друга и всю жизнь нашу предаем, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0276", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неопалимая Купина»"},
  {"id": "cu-mol-0277", "section": "service", "who": "rubric", "text": "(17 сентября)"},
  {"id": "cu-mol-0278", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и поклоняемся Тебе пред святою и пречестною иконою Твоею, еюже дивны и преславны чудеса содеваеши, от огненнаго запаления и молниеноснаго грома жилища наша спасавши, недужныя исцеляеши и всякое благое прошение наше во благо исполняеши."},
  {"id": "cu-mol-0279", "section": "service", "who": "reader", "text": "Смиренно молим Тя, всесильная рода нашего Заступнице, сподоби ны немощныя и грешныя Твоего Матерняго участия и благопопечения. Спаси и сохрани, Владычице, под кровом милости Твоея Церковь Святую, обитель сию, всю страну нашу православную, и вся ны припадающия к Тебе с верою и любовию, и умиленно просящия со слезами Твоего заступления."},
  {"id": "cu-mol-0280", "section": "service", "who": "reader", "text": "Ей, Госпоже Всемилостивая, умилосердися на нас, обуреваемых грехами многими и не имущих дерзновения ко Христу Господу, просити Его о помиловании и прощении, но Тебе предлагаем к Нему на умоление Матерь Его по плоти: Ты же, Всеблагая, простри к Нему Богоприимнии руце Твои и предстательствуй за нас пред Благостию Его, просяще нам прощения прегрешений наших, благочестнаго мирнаго жития, благия христианския кончины, и добраго ответа на страшнем Суде Его."},
  {"id": "cu-mol-0281", "section": "service", "who": "reader", "text": "В час же грознаго посещения Божия, егда огнем возгорятся домы наша, или молниеносным громом устрашаеми будем, яви нам милостивное Твое заступление и державное вспоможение: да спасаеми всесильными Твоими ко Господу молитвами временнаго наказания Божия зде избегнем и вечное блаженство райское тамо унаследуем: и со всеми святыми воспоем Пречестное и Великолепное имя поклоняемыя Троицы, Отца и Сына и Святаго Духа, и Твое велие к нам милосердие, во веки веков. Аминь."},
  {"id": "cu-mol-0282", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неувядаемый Цвет»"},
  {"id": "cu-mol-0283", "section": "service", "who": "rubric", "text": "(16 апреля)"},
  {"id": "cu-mol-0284", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Мати Дево, надеждо христиан и прибежище грешным! Защити всех в несчастиях к Тебе прибегающих, услыши стенания наша, приклони ухо Твое к молению нашему."},
  {"id": "cu-mol-0285", "section": "service", "who": "reader", "text": "Владычице и Мати Бога нашего, не презри требующия Твоея помощи и не отрини нас грешных, вразуми и научи нас, не отступи от нас, рабов Твоих, за роптание наше. Буди нам Мать и Покровительница, вручаем себе милостивому Покрову Твоему. Приведи нас, грешных, к тихой и безмятежной жизни, да оплачем грехи наши."},
  {"id": "cu-mol-0286", "section": "service", "who": "reader", "text": "О Мати Марие, наша преблагая и скорая Заступнице, покрый нас Своим ходатайством, защити от врагов видимых и невидимых, умягчи сердца злых людей, возстающих на нас."},
  {"id": "cu-mol-0287", "section": "service", "who": "reader", "text": "О Мати Господа Творца нашего! Ты еси Корень Девства и Неувядающий Цвет чистоты и целомудрия, пошли помощь нам немощным и обуреваемым плотскими страстьми и блуждающим сердцами. Просвети наши душевныя очи, да видим пути правды Божия."},
  {"id": "cu-mol-0288", "section": "service", "who": "reader", "text": "Благодатию Сына Твоего укрепи нашу слабую волю во исполнение заповедей, да избавимся от всякия беды и напасти и оправданы будем Твоим пречудным заступлением на Страшнем Суде Сына Твоего, Емуже мы воздаем славу, честь и поклонение ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0289", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неупиваемая Чаша»"},
  {"id": "cu-mol-0290", "section": "service", "who": "rubric", "text": "(18 мая)"},
  {"id": "cu-mol-0291", "section": "service", "who": "rubric", "text": "О, Премилосердная Владычице! К Твоему заступлению ныне прибегаем, молений наших не презри, но милостиво услыши нас: жен, детей, матерей и тяжким недугом пианства одержимых, и того ради от матере своея, Церкве Христовой, и спасения отпадающих, братий и сестер и сродник наших исцели."},
  {"id": "cu-mol-0292", "section": "service", "who": "reader", "text": "О Милостивая Мати Божия, коснись сердец их и скоро возстави от падений греховных, ко спасительному воздержанию приведи их. Умоли Сына Своего, Христа Бога нашего, да простит нам согрешения наша и не отвратит милости Своея от людей Своих, но да укрепит нас в трезвении и целомудрии."},
  {"id": "cu-mol-0293", "section": "service", "who": "reader", "text": "Приими, Пресвятая Богородице, молитвы матерей, о чадех своих слезы проливающих, жен, о мужех своих рыдающих, чад сирых и убогих, заблуждшими оставленных, и всех нас, к иконе Твоей припадающих. И да приидет сей вопль наш, молитвами Твоими, ко Престолу Всевышняго."},
  {"id": "cu-mol-0294", "section": "service", "who": "reader", "text": "Покрый и соблюди нас от лукаваго ловления и всех козней вражиих, в страшный же час исхода нашего помози пройти непреткновенно воздушная мытарства, молитвами Твоими избави нас вечнаго осуждения, да покрыет нас милость Божия в нескончаемыя веки веков. Аминь."},
  {"id": "cu-mol-0295", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Нечаянная Радость»"},
  {"id": "cu-mol-0296", "section": "service", "who": "rubric", "text": "(22 декабря и 14 мая)"},
  {"id": "cu-mol-0297", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Всеблагаго Сына Мати Всеблагая, царствующаго града и святаго храма сего Покрове, всех сущих во гресех и скорбех, бедах же и болезнех верная Предстательнице и Заступнице!"},
  {"id": "cu-mol-0298", "section": "service", "who": "reader", "text": "Приими молебное пение сие от нас, недостойных раб Твоих, Тебе возносимое: и якоже древле грешника, на всяк день многажды пред честною иконою Твоею молившагося, не презрела еси, но нечаянную радость покаяния тому даровала еси и усердным к Сыну Твоему ходатайством Сего ко прощению грешника преклонила еси, тако и ныне не презри моления нас, недостойных раб Твоих, и умоли Сына Твоего и Бога нашего, да и всем нам, с верою и умилением пред цельбоносным Образом Твоим покланяющимся, по коегождо потребе нечаянную радость дарует: грешником, во глубине зол и страстей углебающим83 – вседейственное вразумление, покаяние же и спасение; сущим в скорбех и печалех – утешение; в бедах и озлоблениих пребывающим – совершенное сих избытие; малодушным и ненадежным – надежду и терпение; в радости и изобилии живущим – непрестанное Благодетелю Богу благодарение; бедствующим – милость; сущим в болезни – исцеление и укрепление; иждившим84 от недуга ум – ума возвращение и обновление; отходящим в вечную и нескончаемую жизнь – память смертную, умиление и о гресех сокрушение, дух бодр и твердую на милосердие Судии надежду."},
  {"id": "cu-mol-0299", "section": "service", "who": "reader", "text": "О Госпоже Пресвятая! Умилосердися ко всем чтущим всечестное имя Твое и всем яви всемощный покров Твой и заступление: во благочестии, чистоте и честнем жительстве пребывающия до последняго их скончания во благости соблюди; злыя благи сотвори; заблуждшия на путь правый настави; всякому делу благому и Сыну Твоему угодному споспешествуй; всякое злое и богопротивное начинание разруши; в недоумении и злых обстояниих сущим незримую помощь и вразумление с Небесе низпосли; от искушений, соблазнов и погибели спаси, от всех злых человек и от враг видимых и невидимых люди Твоя защити и сохрани; плавающим сплавай; путешествующим спутешествуй; сущим в нужде и гладе буди Питательница; неимущим крова и пристанища буди покров и прибежище; нагим подаждь одеяние, обидимым и неправедно гонимым заступление; клевету, поношение и хуление терпящия незримо оправдай; клеветники и хулители пред всеми обличи; ожесточенно враждующим подаждь примирение, и всем нам друг ко другу любовь и мир, благочестие же и здравие со долгоденствием."},
  {"id": "cu-mol-0300", "section": "service", "who": "reader", "text": "Супружества в любви и единомыслии сохрани; супруги, во вражде и разделении сущия, умири; матерем, дети родящим, скорое подаждь разрешение; младенцы воспитай; юныя уцеломудри, отверзи им ум к восприятию всякаго полезнаго учения, страху Божию, и воздержанию, и трудолюбию настави; от домашния свары единокровныя люди миром и любовию огради; сиротам буди Мати, от всякаго порока и скверны отврати я, и всему благому и богоугодному научи, прельщенныя же и во грех и в нечистоту падшия из бездны погибели изведи; вдовицам буди Утешительница и Помощница, старости буди жезл; от внезапныя смерти без покаяния всех нас избави и всем нам христианскую кончину жизни нашея, безболезненну, непостыдну, мирну и добрый ответ на Страшнем Суде Христове даруй."},
  {"id": "cu-mol-0301", "section": "service", "who": "reader", "text": "Преставльшияся в вере и покаянии от жития сего со Ангелы и всеми святыми жити сотвори, скончавшимся внезапною смертию милостива быти Сына Твоего умоли и о всех усопших, паче же о сих, иже не имут сродников, о упокоении их молящихся, Сама буди непрестанная и теплая Молитвенница и Ходатаица: да вси на Небеси и на земли ведят Тя, яко твердую и непостыдную Предстательницу рода христианскаго, и сие ведуще, славят Тя и Тобою Сына Твоего, со Безначальным Его Отцем и Единосущным Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0302", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Одигитрия» Выдропусская»"},
  {"id": "cu-mol-0303", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "cu-mol-0304", "section": "service", "who": "rubric", "text": "О Царице Небесе и земли, Владычице всемилостивая, Одигитрие85 всечестная, Предстательнице наша усердная, при Кресте Сына Твоего и Бога всыновившая весь падший род человеческий и по успении Своем не оставившая нас сирых и безнадежных!"},
  {"id": "cu-mol-0305", "section": "service", "who": "reader", "text": "Молим Тя, Всенепорочная, благодать Твою не отыми от кающихся рабов Твоих и управи вся, яко Мати Преблагая: защити отечество наше, веру православную сохрани, власти умудри, иереи укрепи, верным людем Твоим помощь неоскудную даруй, юныя вразуми, старость утеши, болящия исцели, отчаянныя возстави, заблуждшия обрати и всем целомудрие и крепость исходатайствуй."},
  {"id": "cu-mol-0306", "section": "service", "who": "reader", "text": "Ты бо еси благая Путеводительница и милосердная Заступница, к Тебе припадаем и молим Тя: не отвержи нас, но испроси нам добраго ответа на Страшнем Судилищи, да не осудимся по грехом и беззаконием нашим, но милость улучим по безмерному человеколюбию Господа и Спасителя нашего Иисуса Христа, Емуже славу и поклонение возсылаем, со Безначальным Его Отцем, и Пресвятым и Благим и Животворящим Его Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0307", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Остробрамской Виленской»"},
  {"id": "cu-mol-0308", "section": "service", "who": "rubric", "text": "(8 января, 27 апреля)"},
  {"id": "cu-mol-0309", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа вышних сил, Небесе и земли Царице и града нашего Киева всемощная Заступнице!"},
  {"id": "cu-mol-0310", "section": "service", "who": "reader", "text": "Приими хвалебное пение сие от нас недостойных раб Твоих, и вознеси молитвы наша ко престолу Сына Твоего и Бога нашего, да милостив будет нам, грешным, и да пробавит благость Свою чтущим Тя и с верою и любовию покланяющимся чудотворному образу Твоему."},
  {"id": "cu-mol-0311", "section": "service", "who": "reader", "text": "К кому бо возопиим Владычице? К кому прибегнем в горестех наших, аще не к Тебе, Царице Небесная? Кто плач наш и воздыхания наша приимет, аще не Ты, Пренепорочная, Надеждо христиан и прибежище нам грешным? Кто паче Тебе в напастех защитит? Тем же молим Тя усердно: покрый Твоим ходатайством наша прегрешения, защити нас от враг видимых и невидимых, умягчи сердца злых человек, возстающих на нас."},
  {"id": "cu-mol-0312", "section": "service", "who": "reader", "text": "О Мати Господа нашего Творца! Ты еси корень девства и неувядаемый цвет чистоты. Приими недостойную молитву нашу и соблюди нас в чистоте душевней, сохрани нас от навета злых человек и от внезапныя смерти, и даруй нам прежде конца покаяние. Помилуй нас в дневных часех и утренних и вечерних, и во всякое время сохрани нас: стоящих, седящих соблюди, и на всяком пути ходящих, и в нощных часех спящих снабди, покрый и заступи. На всяком месте и на всякое время буди нам, Мати Преблагая, стена необоримая и заступление крепкое. Ты хранительница жизни всея нам явися, Пречистая; Ты нас избави от бесов в час смерти; Ты и по смерти упокоение обрести испроси у Сына Твоего и Бога нашего."},
  {"id": "cu-mol-0313", "section": "service", "who": "reader", "text": "Мы же, грешнии, со упованием моления Тебе возносим и умильно вопием: радуйся, Благодатная; радуйся, Обрадованная; радуйся, Преблагословенная; Господь с Тобою, с Тобою с нами. К Тебе прибегаем, яко к несомненней и скорой Заступнице нашей, и Тебе, яко всемогущей Помощнице, сами себе и друг друга и весь живот наш по Христе Бозе предаем, Ему же подобает всякая слава, честь и поклонение со безначальным Его Отцем, со Пресвятым и благим и животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0314", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «О Тебе радуется»"},
  {"id": "cu-mol-0315", "section": "service", "who": "rubric", "text": "(8 января)"},
  {"id": "cu-mol-0316", "section": "service", "who": "rubric", "text": "О Тебе радуется, Благодатная, всякая тварь, Ангельский собор и человеческий род, Освященный Храме и Раю Словесный, Девственная похвало, из Неяже Бог воплотися и Младенец бысть, прежде век Сый Бог наш. Ложесна бо Твоя Престол сотвори. И чрево Твое пространнее Небес содела. О Тебе радуется, Благодатная, всякая тварь, слава тебе."},
  {"id": "cu-mol-0317", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Пермской»"},
  {"id": "cu-mol-0318", "section": "service", "who": "rubric", "text": "(17 июля)"},
  {"id": "cu-mol-0319", "section": "service", "who": "rubric", "text": "О всепетая Богородице Приснодево, Богоизбранная Отроковице! Огради образом Своим чудотворным всю землю Пермскую и всех благочестно живущих на ней от всех наветов вражиих, защити чад своих земных материнским Покровом Своим, укрепи в вере и благочестии всех властей и воинство земли нашей, архипастырем земли Пермстей подаждь мудрость и кротость в несении креста своего, и подаждь нам, Владычице, силу служити ближним своим, и стране нашей подаждь стойкость в испытаниях и веру непоколебиму."},
  {"id": "cu-mol-0320", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Песчанской»"},
  {"id": "cu-mol-0321", "section": "service", "who": "rubric", "text": "(21 июля)"},
  {"id": "cu-mol-0322", "section": "service", "who": "rubric", "text": "О премилостивая и премилосердная Мати Божия, Покровительнице державы нашея, купно же и о всем мире Молитвеннице, приими сердца нашего воздыхания, и услыши коленопреклоненныя молитвы, во умилении душ наших Тебе возсылаемыя, якоже издревле приимала еси молитвы любящих душ зде, пред иконою Твоею возносимыя."},
  {"id": "cu-mol-0323", "section": "service", "who": "reader", "text": "Помози нам в побеждении прелестей и соблазнов мира сего, не попусти нам отверженным быти вечнаго Небеснаго блаженства. Ты Едина наша радость и утешение в жизни сей временней, Ты наша надежда и в Жизни Вечней."},
  {"id": "cu-mol-0324", "section": "service", "who": "reader", "text": "Веруем, яко Ты Своею Матернею любовию и снисхождением удостоиши нас вожделеннаго Царствия Сына Твоего. Тебе убо просим: не отступай от нас, Всеблагая, защищай от всех козней вражиих, не попусти нам чрез грехи наша лишитися милосердия Божия, изжени из нас леность в молитве и посещении храма Божия."},
  {"id": "cu-mol-0325", "section": "service", "who": "reader", "text": "Избави нас от малодушия, уныния, вражды, гнева, подозрения, зависти, клеветы, ненависти и гордости бесовския. Вразуми поправших заповеди Церкве Христовы. Сродником нашим даруй мир и любовь, да согласно поживут родители и дети. Да будет в стране нашей правда Божия, да сохранятся в народе нашем благочестивии обычаи."},
  {"id": "cu-mol-0326", "section": "service", "who": "reader", "text": "Вознеси, о, Всеблагая, усердныя молитвы пред Богом о всего мира умирении, да не погибнет род людский в пламени опустошения всемирнаго, да познают вси народи Отца Своего Небеснаго и Тя, Матерь Божию, Заступницу рода христианскаго."},
  {"id": "cu-mol-0327", "section": "service", "who": "reader", "text": "Приведи вся народы к истинному покаянию и жизни греховныя исправлению, да не осудимся в день Страшнаго Суда Божия, но да сподобит нас Господь вечныя радости в Небесных селениих, Емуже подобает всякая слава, честь и поклонение, Отцу и Сыну и Святому Духу, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0328", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Печерской»"},
  {"id": "cu-mol-0329", "section": "service", "who": "rubric", "text": "(16 мая)"},
  {"id": "cu-mol-0330", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Дево Богородице, наша Печерская похвало и украшение, державный покрове святаго места сего, истинная Владычице избраннаго удела Своего."},
  {"id": "cu-mol-0331", "section": "service", "who": "reader", "text": "Приими нас, недостойных рабов Твоих, убогое моление, с верою и любовию приносящих пред чудным образом Твоим, да посетиши милостивно греховное житие наше, просвещающи его светом покаяния, осени нас, обремененных скорбьми многими, Твоею Небесною радостию, сподоби нас присно славити Тя в мире и благочестии на месте святем сем, да, без порока прешедше путь жития нашего, помощию Твоею достигнем вечнаго веселия во светлости святых и Богоносных отец наших Антония и Феодосия и всех преподобных Печерских и едиными усты и сердцы воспоим Тя с Предвечным Сыном Твоим и Безначальным Его Отцем и Пресвятым, Животворящим, Всеблагим и Единосущным Его Духом во веки веков. Аминь."},
  {"id": "cu-mol-0332", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Покров Пресвятой Богородицы»"},
  {"id": "cu-mol-0333", "section": "service", "who": "rubric", "text": "(14 октября)"},
  {"id": "cu-mol-0334", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа вышних сил, Небесе и земли Царице, града и страны нашея Всемощная Заступнице!"},
  {"id": "cu-mol-0335", "section": "service", "who": "reader", "text": "Приими хвалебно благодарственное пение сие от нас, недостойных раб Твоих, и вознеси молитвы наша ко Престолу Бога Сына Твоего, да милостив будет неправдам нашим, и пробавит благодать Свою чтущим всечестное имя Твое и с верою и любовию покланяющимся чудотворному образу Твоему."},
  {"id": "cu-mol-0336", "section": "service", "who": "reader", "text": "Несмы бо достойни от Него помиловани быти, аще не Ты умилостивиши Его о нас, Владычице, яко вся Тебе от Него возможна суть. Сего ради к Тебе прибегаем, яко к несомненней и скорой Заступнице нашей: услыши нас, молящихся Тебе, осени нас вседержавным покровом Твоим, и испроси у Бога Сына Твоего: пастырем нашим ревность и бдение о душах, градоправителем мудрость и силу, судиям правду и нелицеприятие, наставником разум и смиренномудрие, супругом любовь и согласие, чадом послушание, обидимым терпение, обидящим страх Божий, скорбящим благодушие, радующимся воздержание, всем же нам дух разума и благочестия, дух милосердия и кротости, дух чистоты и правды."},
  {"id": "cu-mol-0337", "section": "service", "who": "reader", "text": "Ей, Госпоже Пресвятая, умилосердися на немощныя люди Твоя; разсеянныя собери, заблуждшия на путь правый настави, старость поддержи, юныя уцеломудри, младенцы воспитай, и призри на всех нас призрением милостиваго Твоего заступления, воздвигни нас из глубины греховныя и просвети сердечныя очи наша ко зрению спасения, милостива нам буди зде и тамо, в стране земнаго пришельствия и на страшнем суде Сына Твоего; преставльшияся же в вере и покаянии от жития сего отцы и братию нашу в вечней жизни со Ангелы и со всеми святыми жити сотвори."},
  {"id": "cu-mol-0338", "section": "service", "who": "reader", "text": "Ты бо еси, Госпоже, Слава Небесных и Упование земных, Ты по Бозе наша Надежда и Заступница всех, притекающих к Тебе с верою. К Тебе убо молимся, и Тебе, яко Всемогущей Помощнице, сами себе и друг друга и весь живот наш предаем, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0339", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Попской»"},
  {"id": "cu-mol-0340", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "cu-mol-0341", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Преславная Госпоже Владычице наша Богородице, воззри милостиво на нас, предстоящих Ти с верою и любовию: приими милостиво наше хвалебное пение сие и пролей ко Господу Богу нашему Твою матернюю молитву о нас, грешных и недостойных, да узрит Он наше покаяние сердечное и, простив нам вся согрешения наша, спасет и помилует нас."},
  {"id": "cu-mol-0342", "section": "service", "who": "reader", "text": "Покажи на нас чудныя милости Твоя, Богомати, смиренно молим Тя: на путь правый нас настави, светом истины умы наша просвети, сердца наша умягчи, веру укрепи, надежду утверди, дара любве к Богу и ближним сподоби, да в единении друг со другом пребывающе, богоугодное житие поживем, и дарами благ земных насладившеся, благ небесных, милосердия ради Божественнаго, не лишимся, да благодарне воспевающе величия Твоя, Пречистая, сподобимся Небеснаго Царствия и тамо со всеми святыми прославим пречестное и великолепое имя в Троице славимаго Бога: Отца и Сына и Святаго Духа. Аминь."},
  {"id": "cu-mol-0343", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Почаевской»"},
  {"id": "cu-mol-0344", "section": "service", "who": "rubric", "text": "(21 сентября и 5 августа)"},
  {"id": "cu-mol-0345", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Царице и Владычице, от всех родов избранная и всеми роды Небесными и земными ублажаемая! Воззри милостивно на предстоящий пред святою иконою Твоею и усердно к Тебе молящийся народ сей, и сотвори предстательством и заступлением Твоим у Сына Твоего и Бога нашего, да никтоже изыдет отсюду упования своего тощ и посрамлен в надежде своей, но да приимет кийждо от Тебе вся, по благому изволению сердца своего и по нужде и потребе своей, во спасение души и во здравие телу."},
  {"id": "cu-mol-0346", "section": "service", "who": "reader", "text": "Призри благосердием, Всепетая Богородице, и на обитель сию, Твоим именем нарицающуюся, юже от лет древних возлюбила еси, избравши ее в достояние Себе, и неоскудно источающи токи исцелений от чудотворныя иконы Твоея и от приснотекущаго источника, в следе стопы Твоея нам открытаго, и сохрани ю от всякаго прилога и навета вражия, якоже древле сохранила еси Твоим явлением целу и неврежденну от лютаго нашествия агарянскаго, да выну воспевается и славится в ней Пресвятое имя Отца, и Сына, и Святаго Духа, и Твое преславное успение, во веки веков. Аминь."},
  {"id": "cu-mol-0347", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Прибавление ума»"},
  {"id": "cu-mol-0348", "section": "service", "who": "rubric", "text": "(воскресенье после 28 августа)"},
  {"id": "cu-mol-0349", "section": "service", "who": "rubric", "text": "Богородице Пречистая, доме, егоже созда Себе Премудрость Божия, даров духовных Подательнице, от мира к премирным ум наш возводящая и всех к познанию разума приводящая!"},
  {"id": "cu-mol-0350", "section": "service", "who": "reader", "text": "Приими молебное пение от нас, недостойных раб Твоих, с верою и умилением покланяющихся пред пречистым образом Твоим. Умоли Сына Твоего и Бога нашего, да дарует властем нашим мудрость и силу, судиям правду и нелицеприятие, пастырем мудрость духовную, ревность и бдение о душах наших, наставником смиренномудрие, чадом послушание, всем же нам дух разума и благочестия, дух смирения и кротости, дух чистоты и правды."},
  {"id": "cu-mol-0351", "section": "service", "who": "reader", "text": "И ныне, всепетая, вселюбимая наша Мати, подай нам ума прибавление, умири, соедини во вражде и разделении сущия и положи им соуз86 любве неразрешимый, всех заблуждших от неразумия к свету истины Христовы обрати, страху Божию, воздержанию и трудолюбию научи, слово премудрости и душеполезное знание просящим даруй, осени нас вечною радостию, Херувимов светлейши и Серафимов честнейши сущая."},
  {"id": "cu-mol-0352", "section": "service", "who": "reader", "text": "Мы же, славная дела и многоразумную премудрость Божию в мире и жизни нашей видяще, устранимся земныя суеты и излишних житейских попечений, и ум и сердце наше на Небеса возведем, яко да Твоим заступлением и помощию славу, хвалу, благодарение и поклонение в Троице славимому Богу и всех Создателю возсылаем, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0353", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Призри на смирение»"},
  {"id": "cu-mol-0354", "section": "service", "who": "rubric", "text": "(29 сентября)"},
  {"id": "cu-mol-0355", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Дево Богородице, высшая Херувим и Честнейшая Серафим, Богоизбранная Отроковице!"},
  {"id": "cu-mol-0356", "section": "service", "who": "reader", "text": "Призри с высоты небесной милостивным Твоим оком на нас, недостойных рабов Твоих, со умилением и слезами молящихся пред Пречистым образом Твоим; не лиши нас Твоего заступления и покрова Державнаго в странствии сем земном, многоскорбном и многомятежнем."},
  {"id": "cu-mol-0357", "section": "service", "who": "reader", "text": "Спаси нас в погибели и скорби сущих, воздвигни из глубины греховныя, просвети ум наш, омраченный страстьми и уврачуй язвы душ и телес наших!"},
  {"id": "cu-mol-0358", "section": "service", "who": "reader", "text": "О Всещедрая Мати Человеколюбиваго Владыки! Удиви на нас пребогатыя милости Твоя, укрепи немощную волю нашу к деланию заповедей Христовых, умягчи окаменелая сердца наша любовию к Богу и ближним, даруй нам сокрушение сердечное и покаяние истинное, да очистившеся от скверны греховныя, сподобимся мирныя христианския кончины и добраго ответа на Страшнем и нелицеприятнем Суде Господа нашего Иисуса Христа, Емуже со Безначальным Его Отцем и Пресвятым, Благим и Животворящим Духом, подобает всякая слава, честь и поклонение, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0359", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Рудненской»"},
  {"id": "cu-mol-0360", "section": "service", "who": "rubric", "text": "(25 октября)"},
  {"id": "cu-mol-0361", "section": "service", "who": "rubric", "text": "Пресвятая Дево Владычице Богородице, милосте Христа моего, обителище Пресвятаго и Животворящаго Духа, надеждо всех святых раб, святое зерцало87 светлости Божия, святейшая Ангел и Архангел, Тебе припадая, усердно молюся: умоли Сына Своего и Бога моего, да отпустит ми всякое прегрешение, вольное и невольное, избавит мя от всех наветов диавольских."},
  {"id": "cu-mol-0362", "section": "service", "who": "reader", "text": "Ей, Владычице, моего падения возведение, простри богоноснеи Свои руце и извлецы мя из глубины греховныя и даждь ми, рабу Твоему (имя рек), всегда угодная Сыну Твоему и Богу моему творити, славя Его вкупе со Безначальным Его Отцем и с Пресвятым и Благим и Животворящим Его Духом, и ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0363", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Скоропослушница»"},
  {"id": "cu-mol-0364", "section": "service", "who": "rubric", "text": "(22 ноября)"},
  {"id": "cu-mol-0365", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышняго, скоропослушная Заступнице всех, к Тебе с верою прибегающих!"},
  {"id": "cu-mol-0366", "section": "service", "who": "reader", "text": "Призри с высоты небеснаго величия Твоего на мя непотребнаго, ко святей иконе Твоей припадающа, услыши скоро смиренную молитву мене грешнаго и принеси ю к Сыну Твоему: умоли Его, да озарит мрачную душу мою светом Божественныя благодати Своея и очистит ум мой от помыслов суетных, да умирит страждущее мое сердце и исцелит раны его, да вразумит мя на добрая дела и укрепит работати Ему со страхом, да простит вся содеянная мною злая, да избавит от вечныя муки и не лишит Небеснаго Своего Царствия."},
  {"id": "cu-mol-0367", "section": "service", "who": "reader", "text": "О Преблагословенная Богородице! Ты благоизволила еси нарещися88 во образе Твоем Скоропослушница, повелевающи всем притекати к Тебе с верою: не презри убо мене скорбнаго и не попусти погибнути мне в бездне грехов моих. На Тя по Бозе все мое упование и надежда спасения, и Твоему покрову и предстательству вручаю себе во веки веков. Аминь."},
  {"id": "cu-mol-0368", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Смоленской»"},
  {"id": "cu-mol-0369", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "cu-mol-0370", "section": "service", "who": "rubric", "text": "О, пречудная и превышшая всех тварей Царице Богородице, Небеснаго Царя Христа Бога нашего Мати, Пресвятая Одигитрие Марие!"},
  {"id": "cu-mol-0371", "section": "service", "who": "reader", "text": "Услыши ны, грешныя и недостойныя, в час сей молящияся и к Тебе со воздыханием и слезами пред Пречистым образом Твоим припадающия, и сице89 умильно глаголющия: изведи нас от рова страстей, Одигитрие Благая, избави нас от всякия скорби и печали, огради от всякия напасти и злых клевет и от неправеднаго навета вражия."},
  {"id": "cu-mol-0372", "section": "service", "who": "reader", "text": "Можеши бо, о Благодатная Мати наша, не точию от всякаго зла сохранити люди Твоя, но и всяким благодеянием снабдити и спасти: разве бо Тебе иныя предстательницы в бедах и обстояниях и теплыя ходатаицы о нас грешных к Сыну Твоему, Христу Богу нашему, не имамы."},
  {"id": "cu-mol-0373", "section": "service", "who": "reader", "text": "Егоже умоли, Владычице, спасти нас и Царствия Небеснаго сподобити, да спасеннии Тобою славим Тя и в будущем веце, якоже спасения нашего Виновницу, и превозносим всесвятое и великолепое имя Отца, и Сына, и Святаго Духа, в Троице славимаго и покланяемаго Бога, во веки веков. Аминь."},
  {"id": "cu-mol-0374", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «София – Премудрость Божия»"},
  {"id": "cu-mol-0375", "section": "service", "who": "rubric", "text": "(28 августа)"},
  {"id": "cu-mol-0376", "section": "service", "who": "rubric", "text": "Непостижимая и Всепетая Премудросте Божия, Софие Преименитая, девственных душе, сиречь90 Единородный Сыне, Слове Божий, приими молебное сие пение от недостойных и скверных уст наших."},
  {"id": "cu-mol-0377", "section": "service", "who": "reader", "text": "Аще и писана суть: не красна песнь во устех грешничих, обаче же разбойник единем словом спасеся, мытарь воздыханием оправдася и хананеина дщерь матерним прошением исцелися, понеже91 Ты, Господи, Благ и Человеколюбив, грядущаго в мир просвещаеши, и грехи грешником отпущаеши, и разумом неразумных наполняеши, и буияго92 умудряеши, и жаждущия благих словес души учением Твоим, яко самаряныню водою живою, напаяеши, блудника целомудренна устрояеши, разбойнику рай отверзаеши, зане Ты еси всех благих Податель, и Вразумитель, и животу Хранитель, Христе Боже наш, и Тебе славу и хвалу, честь и благодарение и славословление возсылаем и поклонение творим со Безначальным Твоим Отцем, и со Пресвятым, и Благим, и Животворящим Твоим Духом, и со Пресвятою и Пренепорочною Твоею Материю, Владычицею нашею Богородицею и Приснодевою Мариею, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0378", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Спасительница утопающих» (Леньковская)"},
  {"id": "cu-mol-0379", "section": "service", "who": "rubric", "text": "(2 января)"},
  {"id": "cu-mol-0380", "section": "service", "who": "rubric", "text": "Заступница усердная, Мати Господа Вышняго! Ты еси всем христианом помощь и заступление, паче же в бедах сущим."},
  {"id": "cu-mol-0381", "section": "service", "who": "reader", "text": "Призри ныне с высоты святыя Твоея и на ны, с верою покланяющияся пречистому образу Твоему, и яви, молим Тя, скорую помощь Твою по морю плавающим и от ветров бурных тяжкия скорби терпящим. Подвигни и вся православныя христианы на спасение в водах утопающих, и воздаждь подвизающимся о сем богатыя милости и щедроты Твоя."},
  {"id": "cu-mol-0382", "section": "service", "who": "reader", "text": "Се бо, на образ Твой взирающе, Тебе, яко милостивно сущей с нами, приносим смиренная моления наша. Не имамы бо ни иныя помощи, ни инаго предстательства, ни утешения, токмо Тебе, о Мати всех скорбящих и напаствуемых."},
  {"id": "cu-mol-0383", "section": "service", "who": "reader", "text": "Ты по Бозе наша Надежда и Заступница, и на Тя уповающе, сами себе, и друг друга, и весь живот наш Тебе предаем во веки веков. Аминь."},
  {"id": "cu-mol-0384", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Спорительница хлебов»"},
  {"id": "cu-mol-0385", "section": "service", "who": "rubric", "text": "(28 октября)"},
  {"id": "cu-mol-0386", "section": "service", "who": "rubric", "text": "О Пресвятая Дево Богородице, Премилостивая Владычице, Царице Небесе и земли, всякаго дома и семейства христианскаго Благоустроительнице, труждающихся благословение, нуждающихся неистощимое богатство, сирых и вдовиц и всех людей Кормительнице!"},
  {"id": "cu-mol-0387", "section": "service", "who": "reader", "text": "Питательнице наша, рождшая Питателя вселенныя и Спорительнице хлебов наших, Ты, Владычице, низпосылаеши Твое Матернее благословение градом нашим, селам и нивам, и коемуждо дому, на Тя упование имущему."},
  {"id": "cu-mol-0388", "section": "service", "who": "reader", "text": "Темже с благоговейным трепетом и сокрушенным сердцем смиренно молим Тя: буди и нам, грешным и недостойным рабом Твоим, мудрая Домостроительница, житие наше добре устрояющая."},
  {"id": "cu-mol-0389", "section": "service", "who": "reader", "text": "Всякое же сообщество, всякий дом и семейство во благочестии и православии, единомыслии, послушании и довольстве соблюди. Нищия и неимущия пропитай, старость поддержи, младенцы воспитай, всех вразуми преискренне взывати ко Господу: «Хлеб наш насущный даждь нам днесь»."},
  {"id": "cu-mol-0390", "section": "service", "who": "reader", "text": "Сохрани, Пречистая Мати, люди Твоя от всякия нужды, болезни, глада, губительства, града, огня, от всякаго злаго обстояния и всякаго нестроения."},
  {"id": "cu-mol-0391", "section": "service", "who": "reader", "text": "Обители нашей (веси), домам и семействам и всякой душе христианстей и всей стране нашей исходатайствуй мир и велию милость, да славим Тя, Премилостивую Питательницу и Кормительницу нашу, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0392", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Споручница грешных»"},
  {"id": "cu-mol-0393", "section": "service", "who": "rubric", "text": "(20 марта, 11 июня)"},
  {"id": "cu-mol-0394", "section": "service", "who": "rubric", "text": "О Владычице Преблагословенная, Защитнице рода христианскаго, прибежище и спасение притекающих к Тебе!"},
  {"id": "cu-mol-0395", "section": "service", "who": "reader", "text": "Вем, воистинну вем, яко зело согреших и прогневах, Премилостивая Госпоже, рожденнаго плотию от Тебе Сына Божия: но имам многии образы прежде мене прогневавших Его благоутробие: мытари, блудницы и прочия грешники, имже дадеся прощение грехов их, покаяния ради и исповедания. Тыя убо образы помилованных очесем грешныя души моея представляя и на толикое Божие милосердие, онех приемшее, взирая, дерзнух и аз грешный прибегнути с покаянием ко Твоему благоутробию."},
  {"id": "cu-mol-0396", "section": "service", "who": "reader", "text": "О Всемилостивая Владычице, да подаси ми руку помощи и испросиши у Сына Твоего и Бога матерними и святейшими Твоими молитвами тяжким моим грехом прощение. Верую и исповедую, яко Той, Егоже родила еси, Сын Твой, есть воистину Христос, Сын Бога Живаго, Судия живых и мертвых, воздаяй комуждо по делом его."},
  {"id": "cu-mol-0397", "section": "service", "who": "reader", "text": "Верую же паки и исповедую Тебе быти истинную Богородицу, милосердия источник, утешение плачущих, взыскание погибших, сильную и непрестающую к Богу Ходатаицу, зело любящую род христианский, и Споручницу покаяния."},
  {"id": "cu-mol-0398", "section": "service", "who": "reader", "text": "Воистинну бо несть человеком иныя помощи и покрова, разве Тебе, Госпоже Премилостивая, и никтоже уповая на Тя постыдеся когда, и Тобою умоляя Бога, никтоже оставлен бысть. Того ради молю Твою неисчетную благость: отверзи двери милосердия Твоего мне, заблудшему и падшему в тимение93 глубины, не возгнушайся мене сквернаго, не презри грешнаго моления моего, не остави мене окаяннаго, яко в погибель злобный враг похитити мя ищет, но умоли о мне рожденнаго от Тебе милосердаго Сына Твоего и Бога, да простит великия моя грехи, и избавит мя от пагубы моея: яко да и аз со всеми получившими прощение воспою и прославлю безмерное милосердие Божие и Твое непостыдное о мне заступление в жизни сей и в нескончаемом веце. Аминь."},
  {"id": "cu-mol-0399", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Страстной»"},
  {"id": "cu-mol-0400", "section": "service", "who": "rubric", "text": "(26 августа)"},
  {"id": "cu-mol-0401", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Владычице Богородице, вышши еси всех Ангел и Архангел и всея твари честнейши, Помощница еси обидимых, ненадеющихся надеяние, убогих Заступница, печальных утешение, алчущих Кормительница, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление."},
  {"id": "cu-mol-0402", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже, Дево Богородице, Владычице, милостию Твоею спаси и помилуй раб Твоих, Великаго Господина и отца нашего Святейшаго Патриарха (имя рек), и преосвященныя митрополиты, архиепископы и епископы, и весь священнический и иноческий чин, Богохранимую страну нашу, военачальники, градоначальники и христолюбивое воинство и доброхоты, и вся православныя христианы ризою Твоею честною защити, и умоли, Госпоже, из Тебе без семене воплотившагося Христа Бога нашего, да препояшет нас силою Своею свыше на невидимыя и видимыя враги наша."},
  {"id": "cu-mol-0403", "section": "service", "who": "reader", "text": "О Всемилостивая Госпоже, Владычице Богородице, воздвигни нас из глубины греховныя и избави нас от глада, губительства, от труса и потопа, от огня и меча, от нахождения иноплеменных и междоусобныя брани, и от напрасныя смерти, и от нападения вражия, и от тлетворных ветр, и от смертоносныя язвы, и от всякаго зла."},
  {"id": "cu-mol-0404", "section": "service", "who": "reader", "text": "Подаждь, Госпоже, мир и здравие рабом Твоим, всем православным христианом, и просвети им ум и очи сердечныя, еже ко спасению, и сподоби ны, грешныя рабы Твоя, Царствия Сына Твоего, Христа Бога нашего, яко держава Его благословена и препрославлена, со Безначальным Его Отцем, и с Пресвятым и Благим и Животворящим Его Духом, ныне, и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0405", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Табынской»"},
  {"id": "cu-mol-0406", "section": "service", "who": "rubric", "text": "(9-я пятница после Пасхи)"},
  {"id": "cu-mol-0407", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Мати Господа нашего Иисуса Христа, непрестанная о нас пред Богом Молитвеннице и Ходатаице."},
  {"id": "cu-mol-0408", "section": "service", "who": "reader", "text": "О Мати наша Преблагая, всех нас при Кресте Сына Твоего усыновившая. Благодарим Тя, безчисленныя блага молитвою Своею нам испросившая. Благодарим Тя, множество икон Твоих чудотворных стране нашей даровавшая. Благодарим Тя, дивную икону Табынскую в годину скорбей краю Уральскому пославшая, на камени велием икону Свою нам явившая, молим Тя: окамененныя сердца наша росою молитв Твоих умягчи."},
  {"id": "cu-mol-0409", "section": "service", "who": "reader", "text": "Милость Свою нам показавшая у источника воднаго, идеже болезни наша телесныя исцеляются, даруй нам потоки скорбных слез и очисти ими тину94 грехов наших. У источника воднаго святою иконою Твоею благословение месту сему показавшая, помози нам слово Господа Сына Твоего исполнити и солию земли быти."},
  {"id": "cu-mol-0410", "section": "service", "who": "reader", "text": "Лик Свой темным, нам, грешным, омраченным грехом явившая, просвети тьму грехов наших и приведи нас к тихому пристанищу в вечныя обители, уготованныя Господом любящим Его. Аминь."},
  {"id": "cu-mol-0411", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Тихвинской»"},
  {"id": "cu-mol-0412", "section": "service", "who": "rubric", "text": "(9 июля)"},
  {"id": "cu-mol-0413", "section": "service", "who": "rubric", "text": "Благодарим Тя, о Преблагая и Пречистая, Преблагословенная Дево, Владычице, Мати Христа Бога нашего, о всех благодеяниих Твоих, яже показала еси роду человеческому, наипаче же нам, христоименитым людем российским, о нихже ниже самый ангельский язык к похвалению доволен95 будет."},
  {"id": "cu-mol-0414", "section": "service", "who": "reader", "text": "Благодарим Тя, якоже и ныне удивила еси неизреченную Твою милость на нас, недостойных рабех Твоих, преестественным самопришествием Пречистыя Твоея иконы, ею же всю просветила еси Российскую страну."},
  {"id": "cu-mol-0415", "section": "service", "who": "reader", "text": "Темже и мы, грешнии, со страхом и радостию покланяющеся, вопием Ти: о Пресвятая Дево, Царице и Богородице, спаси и помилуй люди Твоя, и подаждь им победы на вся враги их, и сохрани царствующия грады, и вся грады и страны христианския, и сей святый храм от всякаго навета вражия избави, и всем вся на пользу даруй, ныне пришедшим с верою и молящимся рабом Твоим, и поклоняющимся Пресвятому образу Твоему, яко благословенна еси с рождшимся от Тебе Сыном и Богом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0416", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Толгской»"},
  {"id": "cu-mol-0417", "section": "service", "who": "rubric", "text": "(21 августа)"},
  {"id": "cu-mol-0418", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Дево Богородице, вышшая Херувимов и Серафимов и святейшая всех святых! Ты, Всеблагая, на Толге икону Твою многоцелебную блаженному святителю Трифону огневидно явити благоволила еси, и ею многая и неизреченная чудеса соделала еси, и ныне содеваеши, по Твоему неизреченному к нам милосердию."},
  {"id": "cu-mol-0419", "section": "service", "who": "reader", "text": "Тебе пред пречистым образом Твоим припадаем и молимся, Преблагословенная рода нашего Заступнице: в странствии сем земнем, многоскорбнем и многомятежнем, не лиши нас Твоего заступления и покрова державнаго. Спаси и защити нас, Владычице, от разжженных стрел лукаваго врага спасения нашего."},
  {"id": "cu-mol-0420", "section": "service", "who": "reader", "text": "Укрепи немощную волю нашу к деланию заповедей Христовых, умягчи окаменелая сердца наша любовию к Богу и ближним нашим, даруй нам сокрушение сердечное и покаяние истинное, да, очистившеся от скверны греховныя, возможем принести Творцу благоугодныя Ему плоды добрых дел и сподобитися мирныя христианския кончины и ответа праваго на страшнем и нелицеприятнем Суде Его."},
  {"id": "cu-mol-0421", "section": "service", "who": "reader", "text": "Ей, Госпоже Всемилостивая! В час грозный смертный наипаче яви нам Твое многомощное заступление, ускори тогда на помощь к нам, безпомощным, и державною рукою Твоею исхити нас из власти лютаго миродержца, ибо воистину много может молитва Твоя пред лицем Господа, и ничтоже невозможно ходатайству Твоему, аще токмо восхощеши."},
  {"id": "cu-mol-0422", "section": "service", "who": "reader", "text": "Темже, на святый образ Твой умиленно взирающе и пред ним, яко живей Ти сущей с нами, покланяющеся, с упованием благим сами себе, и друг друга, и весь живот наш Тебе по Бозе молитвенно предаем и Тя величаем с рождшимся от Тебе Спасителем нашим, Господом Иисусом Христом, Емуже, со Безначальным Его Отцем и Пресвятым Духом, подобает всякая слава, честь и поклонение, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0423", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Трех Радостей»"},
  {"id": "cu-mol-0424", "section": "service", "who": "rubric", "text": "(8 января)"},
  {"id": "cu-mol-0425", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, всеблагаго Сына Мати всеблагая, царствующаго града и святаго храма сего покровительнице, всем сущим во гресех, скорбех, бедах и болезнех верная предстательнице и заступнице!"},
  {"id": "cu-mol-0426", "section": "service", "who": "reader", "text": "Не презри моления нас, недостойных рабов Твоих, и умоли Сына Твоего и Бога нашего, да всем нам, с верою и умилением поклоняющимся пред чудотворным образом Твоим, дарует по коегождо потребе радость: сущим в скорбех и печалех утешение, бедствующим милосердие, сущим в многонедужии нечаемое исцеление и укрепление."},
  {"id": "cu-mol-0427", "section": "service", "who": "reader", "text": "О Госпоже Пресвятая, умилосердися ко всем чтущим всечестное имя Твое и всем яви всемощный покров Твой и заступление: всякому делу, Сыну Твоему угодному споспешествуй; всякое дело злое разруши; в недоумении и трудных и опасных обстояниих обретающимся незримую помощь и вразумление с небесе ниспосли."},
  {"id": "cu-mol-0428", "section": "service", "who": "reader", "text": "Младенцы воспитай, юныя уцеломудри, отверзи им ум к приятию всякаго полезнаго учения. От домашния брани и от врагов видимых и невидимых защити и сохрани. Супружества в любви и единомыслии сохрани и от вражды единокровных миром и любовию огради. И всем нам даждь друг ко другу любовь, мир и благочестие, и здравие с долгоденствием."},
  {"id": "cu-mol-0429", "section": "service", "who": "reader", "text": "Преставившияся в вере и покаянии от жития сего со ангелы и всеми святыми жити сотвори, да вси на Небеси и на земли ведят Тя яко твердую и непостыдную Предстательницу нашу, рода христианскаго, и, ведуще, славят Тя и Тобою Сына Твоего, со Безначальным Его Отцем и Единосущным Его Духом, ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0430", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Троеручица»"},
  {"id": "cu-mol-0431", "section": "service", "who": "rubric", "text": "(11 июля и 25 июля)"},
  {"id": "cu-mol-0432", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Дево, Богородице Марие! Припадаем и покланяемся Тебе пред святою иконою Твоею, воспоминающе преславное чудо Твое, исцелением усеченныя десницы преподобнаго Иоанна Дамаскина от иконы сея явленное, егоже знамение доныне видимо есть на ней, во образе третия руки, ко изображению Твоему приложенныя."},
  {"id": "cu-mol-0433", "section": "service", "who": "reader", "text": "Молимся Ти и просим Тя, всеблагую и всещедрую рода нашего Заступницу: услыши нас, молящихся Тебе, и якоже блаженнаго Иоанна, в скорби и болезни к Тебе возопившаго, услышала еси, тако и нас, скорбящих и болезнующих ранами страстей многоразличных, не презри, усердно к Тебе от души сокрушенныя прибегающих. Ты зриши, Госпоже Всемилостивая, немощи наша, озлобление наше, нужду, во Твоей помощи потребу, яко отвсюду врази окружают нас, и несть помогающаго, ниже заступающаго, аще не Ты умилосердишися о нас, Владычице."},
  {"id": "cu-mol-0434", "section": "service", "who": "reader", "text": "Ей, молим Ти ся, вонми гласу болезненному нашему и помози нам святоотеческую православную веру до конца дней наших непорочно сохранити, во всех заповедех Господних неуклонно ходити, покаяние истинное о гресех наших всегда Богу приносити и сподобитися мирныя христианския кончины и добраго ответа на Страшнем Суде Сына Твоего и Бога нашего, Егоже умоли за нас Матернею молитвою Твоею, да не осудит нас по беззаконием нашим, но да помилует нас по велицей и неизреченней милости Своей."},
  {"id": "cu-mol-0435", "section": "service", "who": "reader", "text": "О Всеблагая! Услыши нас и не лиши нас помощи Твоея державныя, да Тобою спасение получивше, воспоем и прославим Тя на земли живых и рождшагося от Тебе искупителя нашего, Господа Иисуса Христа, Емуже подобает слава и держава, честь и поклонение, купно со Отцем и Святым Духом, всегда, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0436", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «У источника» Пюхтицкой»"},
  {"id": "cu-mol-0437", "section": "service", "who": "rubric", "text": "(1 июля)"},
  {"id": "cu-mol-0438", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и покланяемся Тебе пред светозарным образом Твоим и смиренно молим: прости, Всемилостивая, вся заблуждения наша и вся оскорбления, в ведении или в неведении Сыну Твоему и Спасителю нашему от юности обильно нанесенная неисполнением заповедей Его святых, небрежением к святыне, нерадением в молитве и нетерпением в несении креста нашего."},
  {"id": "cu-mol-0439", "section": "service", "who": "reader", "text": "Призри на жажду спасения и несильныя труды и пребуди с многогрешным, но оставшимся верным Сыну Твоему малым Его стадом по неложному слову Его, во Святем Евангелии реченному: «Не бойся, малое стадо: яко благоизволи Отец ваш дати вам Царство»."},
  {"id": "cu-mol-0440", "section": "service", "who": "reader", "text": "О Животворящий Источниче нашего утешения, к Тебе возносим смиренное сие моление и просим Матерняго Твоего о нас заступления пред Престолом Отца нашего Небеснаго."},
  {"id": "cu-mol-0441", "section": "service", "who": "reader", "text": "Не лиши нас Царства сего благодатнаго за премногия грехи наша, ибо вемы, яко ничто внешнее и самолюбивое, гордое и тщеславное, ни славныя достижения мирския, ни добродетели, с тайным самолюбованием совершаемыя, ни степени, ни чины, ни самое иноческое звание не возмогут возвести нас в Царствие Небесное, токмо сердце чистое и дух сокрушенный и смиренный, за многия молитвенныя труды Духом Святым даруемыя."},
  {"id": "cu-mol-0442", "section": "service", "who": "reader", "text": "Помози нам оставшиеся дни жизни нашея в духе и истине покланятися Сыну Твоему, Милосердная Богородице, и, стяжав нелицемерную любовь к Богу и ближнему, исполнити сию первейшую заповедь Господню, единственно приводящую в Царство Небесное."},
  {"id": "cu-mol-0443", "section": "service", "who": "reader", "text": "Не взирая на недостоинство наше, сподоби нас соделатися чадами Божиими по благодати и наследовати жизнь вечную со всеми, в покаянии Богу угодившими, и введи нас, Мати Божия, язвами Сына Твоего Иисуса Претихаго в Небесный Чертог Его, дабы вечно славити и воспевати Пречестное и Великолепое имя Всесвятыя Троицы Отца и Сына и Святаго Духа ныне и присно и во веки веков. Аминь."},
  {"id": "cu-mol-0444", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умиление» (Серафимо-Дивеевской)"},
  {"id": "cu-mol-0445", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "cu-mol-0446", "section": "service", "who": "rubric", "text": "О Владычице Богородице, души моея услаждение, изсохшаго сердца моего струе Боготочная, потемненнаго ума моего пресветлый светильниче, ленивыя воли моея Путеводительнице, немощи моея сило, наготы облечение, нищеты богатство, неисцелимых ран мощное и скорое врачевание, слез осушение, рыданий утоление, бед претворение, болезней облегчение, уз разрешение, спасения надеждо!"},
  {"id": "cu-mol-0447", "section": "service", "who": "reader", "text": "Услыши молитву мою: даждь ми время покаяния, ревность спасения, силу в подвизех Богоугождения; сохрани мя от напастей и всяких зол, во искушениих же и бедах простри Твою руку помощи, да возстану в падении и не погибну люте. Дондеже пребываю в сем многоболезненнем житии, не лиши мене даров Твоея милости."},
  {"id": "cu-mol-0448", "section": "service", "who": "reader", "text": "Ущедри благостынею Твоею всю христолюбивую братию, зде предстоящую и молящуюся. Младенцы воспитай, юныя настави, старыя поддержи, малодушныя утеши, заблуждшия вразуми, вдовицы и сирыя призри и защити, на всех любящих и ненавидящих нас излей богатую Твою милость."},
  {"id": "cu-mol-0449", "section": "service", "who": "reader", "text": "И при кончине жизни моея, во время исхода моего от телесе, буди ми Предстательница: болезнь смертную умягчи, тоску утоли и бедную мою душу приведи к вечным обителем, да не возьмет мене темная сила, ниже да увлечет во глубину ада."},
  {"id": "cu-mol-0450", "section": "service", "who": "reader", "text": "Ей, Преблагая Владычице Богородице, души моея умиление! Согрей хладное в вере и любви сердце мое слезами умиления: низпосли ми, скорбящему и обремененному грехми, за молитвы преподобнаго отца Серафима, Твоего чтителя, потребную радость и утешение. Да не лишуся Убо, Богоневесто, упования моего плода, но да сподоблюся в Бозе и Спасителе моем, возлюбленном Сыне Твоем, Господе нашем Иисусе Христе, сей прияти. Тому слава и держава, честь и поклонение, со Безначальным Его Отцем, и Всесвятым и Благим и Животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0451", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умиление» (Псково-Печерской)"},
  {"id": "cu-mol-0452", "section": "service", "who": "rubric", "text": "(20 октября, Неделя 7-я по Пасхе, 3 июня, 6 июля, 8 сентября)"},
  {"id": "cu-mol-0453", "section": "service", "who": "rubric", "text": "О Преблагословенная Дево Богородице Владычице! Мати всех страждущих и болезнующих сердцем! Страны нашея и града Защитнице!"},
  {"id": "cu-mol-0454", "section": "service", "who": "reader", "text": "Обители Псково-Печерския красото и славо! Призри на нас смиренных, обремененных грехи многими, отягченных скорбьми и печалями, и с сокрушением и слезами взирающих на пречистый лик Твой, в чудотворней иконе явленный."},
  {"id": "cu-mol-0455", "section": "service", "who": "reader", "text": "Сохрани от всякаго зла святую обитель сию, юже преподобный Корнилий со старцы Марком и Ионою Тебе вручи и всех в вере и надежде подвизающихся в ней."},
  {"id": "cu-mol-0456", "section": "service", "who": "reader", "text": "Спаси и град сей, и вся люди, правоверно живущия и к Тебе прибегающия, от нашествия иноплеменных, от всякаго страха и труса, от мора и глада, от злых человек и всяческой скорби."},
  {"id": "cu-mol-0457", "section": "service", "who": "reader", "text": "Приникни к нам милосердием Твоим, яко ликом Твоим Божественным любезно приникла еси к ланите Богомладенца."},
  {"id": "cu-mol-0458", "section": "service", "who": "reader", "text": "Согрей нас дыханием Твоея любве и никогда же отступай от нас, ни в сей жизни, ни в будущей, да чающе Твою всесильную Материнскую помощь, сподобимся безбедно дойти вечныя жизни и прославлять Небеснаго Отца и Сына и Святаго Духа, в Троице славимаго Бога, во веки веков. Аминь."},
  {"id": "cu-mol-0459", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умягчение злых сердец»"},
  {"id": "cu-mol-0460", "section": "service", "who": "rubric", "text": "(в Неделю Всех святых)"},
  {"id": "cu-mol-0461", "section": "service", "who": "rubric", "text": "О многострадальная Мати Божия, превысшая всех дщерей земли по чистоте Твоей и по множеству страданий, Тобою на земли перенесенных! Приими многоболезненная воздыхания наша и сохрани нас под кровом Твоея милости."},
  {"id": "cu-mol-0462", "section": "service", "who": "reader", "text": "Иного бо прибежища и теплаго предстательства, разве Тебе, не вемы, но яко дерзновение имущи ко Иже из Тебе Рожденному, помози и спаси ны молитвами Твоими, да непреткновенно достигнем Царствия Небеснаго, идеже со всеми святыми будем воспевати в Троице Единаго Бога, всегда, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0463", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Успение» Киево-Печерская»"},
  {"id": "cu-mol-0464", "section": "service", "who": "rubric", "text": "(16 мая, 28 августа)"},
  {"id": "cu-mol-0465", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Дево Богородице, наша Печерския похвало и украшение, покрове и заступление, истинная Владычице избраннаго удела Твоего; приими нас, недостойных рабов Твоих, убогое моление с верою и любовию приносящих пред чудным образом Твоим."},
  {"id": "cu-mol-0466", "section": "service", "who": "reader", "text": "Да посетиши милостивно греховное житие наше, просвещающе его светом покаяния, осени нас, обремененных скорбьми многими, Твоею небесною радостию, и сподоби нас присно славити Тя в мире и благочестии во обители Печерстей, и зде без порока прешедше путь жития нашего, помощию Твоею достигнем вечнаго веселия во светлостех святых и Богоносных отец наших Антония и Феодосия и всех преподобных Печерских, и едиными усты и сердцы воспоем Тя и Предвечнаго Сына Твоего, со Безначальным Его Отцем и Пресвятым, Всеблагим, Животворящим и Единосущным Его Духом во веки веков. Аминь."},
  {"id": "cu-mol-0467", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Утоли моя печали»"},
  {"id": "cu-mol-0468", "section": "service", "who": "rubric", "text": "(7 февраля)"},
  {"id": "cu-mol-0469", "section": "service", "who": "reader", "text": "Тебе просим и Тебе молим, сострадательнейшую Матерь человеколюбиваго Владыки: буди милостива к нам, смиренным и недостойным рабом Твоим, призри благосердием на пленение и смирение наше, уврачуй сокрушения душ и телес наших, разсей видимыя и невидимыя враги, буди нам недостойным столп крепок пред лицем враг наших, бранное оружие, сильное ополчение, Воевода и необоримая Поборница: яви ныне на нас древния и дивныя милости Твоя, да уведят беззаконнии врази наши, яко Сын Твой и Бог Един есть Царь и Владыка, яко Ты еси воистину Богородица, рождшая по плоти Истиннаго Бога, яко вся Тебе возможна суть, и елика аще восхощеши, Владычице, власть имаши вся сия совершити на Небеси и на земли, и на всяко прошение даровати, елика коемуждо полезна суть: болящим здравие, в мори же сущим тишину и благое плавание."},
  {"id": "cu-mol-0470", "section": "service", "who": "reader", "text": "Путешествующим убо спутешествуй и сохраняй я, плененныя спасай от горькаго рабства, утеши печальныя, облегчи нищету и всякое иное телесное злострадание: всех свободи от душевных недуг и страстей невидимыми Твоими предстательствы и наставлении, яко да безпорочно и непреткновенно путь сея временныя жизни совершивше, наследим Тобою и оная вечная блага во Царствии Небеснем."},
  {"id": "cu-mol-0471", "section": "service", "who": "reader", "text": "Спаси молитвами Твоими, Владычице, сию Тебе наипаче посвященную паству, всякий град и страну, от глада, труса, потопа, огня, меча, нашествия иноплеменников, междоусобныя брани, и всякий праведно на ны движимый гнев отврати, благоволением и благодатию Единороднаго Сына и Бога Твоего, Емуже подобает всякая слава, честь и поклонение, со Безначальным Его Отцем, и со Присносущным и Животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0472", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Феодоровской»"},
  {"id": "cu-mol-0473", "section": "service", "who": "rubric", "text": "(27 марта и 29 августа)"},
  {"id": "cu-mol-0474", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице и Приснодево Марие, единая надеждо нам грешным! К Тебе прибегаем и Тебе молим, яко велие имаши дерзновение к рождшемуся от Тебе по плоти Господу Богу и Спасителю нашему Иисусу Христу."},
  {"id": "cu-mol-0475", "section": "service", "who": "reader", "text": "Не презри слез наших, не возгнушайся воздыханий наших, не отрини скорби нашея, не посрами упования нашего на Тя, но Матерними молении Твоими умоли Господа Бога, да сподобит нас, грешных и недостойных, свободитися от грехов и страстей душевных и телесных, и миру убо умрети96, а Ему Единому жити по вся дни жизни нашея."},
  {"id": "cu-mol-0476", "section": "service", "who": "reader", "text": "О Пресвятая Владычице Богородице! Путешествующим спутешествуй и ограждай и охраняй оныя, избави плененных от пленения, свободи страждущих от бед, утеши сущих в печали, скорбех и напастех, облегчи нищету и всяко злострадание телесное, и даруй всем вся потребная к животу, благочестию и жизни временней."},
  {"id": "cu-mol-0477", "section": "service", "who": "reader", "text": "Спаси, Владычице, вся страны и грады, и сию страну и сей град, имже сия чудотворная и святая икона Твоя дадеся во утешение и ограждение: избави я от глада, губительства, труса, потопа, огня, меча, нашествия иноплеменных, междоусобныя брани, и отврати всякий гнев, на ны праведно движимый."},
  {"id": "cu-mol-0478", "section": "service", "who": "reader", "text": "Даруй нам время на покаяние и обращение, избави нас от внезапныя смерти и во время исхода нашего предстани нам явльшися, Дево Богородице, и избави нас от воздушных мытарств князей века сего, сподоби на Страшнем Суде Христове стати одесную, и соделай нас наследники вечных благ, да славим великолепое имя Сына Твоего и Бога нашего со Безначальным Его Отцем, и Святым и Благим и Животворящим Его Духом, ныне и присно, и во веки веков. Аминь."},
  {"id": "cu-mol-0479", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Цареградской»"},
  {"id": "cu-mol-0480", "section": "service", "who": "rubric", "text": "(8 мая, 30 сентября)"},
  {"id": "cu-mol-0481", "section": "service", "who": "rubric", "text": "К Тебе, Пресвятей Госпоже Богородице, недостойнии раби Твои прибегаем: Ты бо, Преблагая, едина незлобивая и велемощная к Сыну Твоему, Христу Богу нашему, за ны, грешныя, Ходатаица и Непостыдная Предстательница."},
  {"id": "cu-mol-0482", "section": "service", "who": "reader", "text": "Веси, яко зело преогорчихом благость Его преступлением Божественных Его заповедей. Несть бо греха, егоже мы, непотребнии, не сотворихом, всяк страх отвергши, того ради и Духа благодати и дара преестественнаго сыноположения97 отвергохомся и всякаго отвращения и казни достойни сотворихомся."},
  {"id": "cu-mol-0483", "section": "service", "who": "reader", "text": "Веси, Преблагая Заступнице, яко и Твоя милости и дарования мы, безумнии, забвению предахом и Твоего милосердия недостойни содеяхомся. Колико бо Тя, Госпоже Богородительнице, на умоление Сына Твоего и Бога нашего подвизахом, обещавше Ти, Пречистая, от злых исправление, толико Твое матернее к Нему за ны, грешныя, предстательство и заступление нивочтоже вменихом, неблагодарни и злонравни суще. Ныне стыд носяще и ниже достойни воззрети на пречистый образ Твой, пред нимже предстахом."},
  {"id": "cu-mol-0484", "section": "service", "who": "reader", "text": "Но, о свете душ наших, светлое зерцало благости Божия! И мы вемы, колико может Твое матернее ко Христу Богу нашему дерзновение, вемы, яко никтоже, прибегаяй к Тебе, Благосердая, с покаянием и умилением, посрамлен от Тебе бысть, или призываяй Тебе, Пречистая, не услышан от Тебе изыде: чтит бо Сын Твой Тя, Богоневесто, яко Матерь Свою, милостивно приемля моления Твоя."},
  {"id": "cu-mol-0485", "section": "service", "who": "reader", "text": "Сего ради и ужасаемся воззрети к Свету Твоея страшныя и Богоподобныя славы, осквернены имуще очи душевныя, обаче колена душ и телес наших преклоняюще, молим Тя, Боголепная Марие, яко Матерь и Царицу нашу: умилосердися на ны, непотребныя рабы Твоя, и, имиже веси судьбами, взыщи ны, погибшия, просвети наш ум светом Твоего Боговедения, да, им озарени суще, всякое злое помышление и всяк безстудных деяний образ до конца отсечем, всем же сердцем заповеди Господни возлюбим и в них непорочно ходити начнем."},
  {"id": "cu-mol-0486", "section": "service", "who": "reader", "text": "Еретическая возстания прекрати, разсеянныя же собери, заблуждшия возврати во едино стадо Сына Твоего, Христа Бога нашего, старость поддержи, юныя вразуми, вдовиц и сирот защити, болящия исцели, страну же нашу миром огради и во веки незыблему соблюди, всем же нам преспеяние в вере и делех благих в долготу дней даруй."},
  {"id": "cu-mol-0487", "section": "service", "who": "reader", "text": "Прежде отшедшия отцы и братию нашу во светлостех райских и селениих праведных упокой, с ними и нас всех в покаянии и исповедании приими и сопричти, да и мы, Преблагая наша Заступнице, Богомати и Владычице, спасени суще Твоим ходатайством, восхваляя Тя, прославим со всеми святыми пречестное и пресвятое имя Отца и Сына и Святаго Духа, Единаго в Троице славимаго Бога, ныне, и присно, и во веки. Аминь."},
  {"id": "cu-mol-0488", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Целительница»"},
  {"id": "cu-mol-0489", "section": "service", "who": "rubric", "text": "(1 октября)"},
  {"id": "cu-mol-0490", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Ченстоховской»"},
  {"id": "cu-mol-0491", "section": "service", "who": "rubric", "text": "(19 марта)"},
  {"id": "cu-mol-0492", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Царице Богородице, от всех родов избранная и всеми роды небесными и земными ублажаемая! Воззри милостивно на предстоящия пред святою иконою Твоею люди сия, усердно молящиеся Тебе и сотвори предстательством Твоим и заступлением у Сына Твоего и Бога нашего, да никтоже отыдет от места сего упования своего тощ и посрамлен в надежде своей; но да приимет кийждо от Тебе вся по благому изволению сердца своего, по нужди и потребе своей, во спасение души и во здравие телу."},
  {"id": "cu-mol-0493", "section": "service", "who": "reader", "text": "Моли, Милосердая Владычице, пренебеснаго Бога, да присно церковь свою святую соблюдет, вышним своим благословением архиереев наших православных укрепит, миром оградит и святей своей церкви целых, здравых, честных, долгоденствующих и право правящих слово своея истины дарует, от всех же видимых и невидимых врагов со всеми православными христианы милостивно избавит и во Православии и твердей вере до конца веков неотступно и неизменно сохранит."},
  {"id": "cu-mol-0494", "section": "service", "who": "reader", "text": "Призирай благосердием, Всепетая, и призрением милостиваго Твоего заступления на все царство наше Всероссийское, царствующия грады наша, град сей и святой храм сей, и излей на ня богатыя Твоя милости, Ты бо еси всесильная Помощница и Заступница всех нас."},
  {"id": "cu-mol-0495", "section": "service", "who": "reader", "text": "Приклонися к молитвам и всех раб Твоих, притекающих зде ко святей иконе Твоей сей, услыши воздыхания и гласы, ими же раби Твои молятся во святем храме сем. Аще же и иноверный, и иноплеменник, идя и проходя зде, помолится, услыши, чадолюбивая Госпоже, и сего человеколюбие и милостивно соделай, яже к помощи ему и ко спасению."},
  {"id": "cu-mol-0496", "section": "service", "who": "reader", "text": "Ожесточенныя же и разсеянныя сердцы своими во странах наших на путь истины настави. Отпадшия от благочестивыя веры обрати и паки сопричти святей Твоей Православней кафолической церкви."},
  {"id": "cu-mol-0497", "section": "service", "who": "reader", "text": "В семействах людей всех и во братии нашей мир огради и соблюди, в юных братство и смиренномудрие утверди, старость поддержи, отрочество настави, мужество умудри, сирыя и вдовицы заступи, утесненныя и в скорбех сущия утеши и охрани, младенцы воспитай, болящия уврачуй, плененныя свободи, ограждая ны выну98 от всякаго зла благостию Твоею и утеши милостивным Твоим посещением и всех благодеющих нам."},
  {"id": "cu-mol-0498", "section": "service", "who": "reader", "text": "Даруй же, Благая, земли плодоносие, воздуху благорастворение и вся, яже на пользу нашу, дары благовременныя и благопотребныя, всемощным своим предстательством пред Всесвятою Живоначальною Троицею, купно со святыми избранными угодниками Ея Кириллом и Мефодием."},
  {"id": "cu-mol-0499", "section": "service", "who": "reader", "text": "Прежде отшедшия отцы и матери, братия и сестры наша, и вся от лет древних припадавшия ко святей иконе Твоей сей упокой в селениях святых, в месте светле, в месте злачне, в месте покойне, идеже несть печаль и воздыхание."},
  {"id": "cu-mol-0500", "section": "service", "who": "reader", "text": "Егда же приспеет и наше от жития сего отшествие и к вечной жизни преселение, предстани нам, Преблагословенная Дево, и даруй христианскую кончину живота нашего безболезненну, непостыдну, мирну и Святых Тайн причастну, да и в будущем веце сподобимся вси, купно со всеми святыми, безконечныя блаженныя жизни во царствии возлюбленнаго Сына Твоего, Господа и Спаса нашего Иисуса Христа, Ему же подобает всякая слава, честь и поклонение во веки веков. Аминь."},
  {"id": "cu-mol-0501", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Черниговской-Гефсиманской»"},
  {"id": "cu-mol-0502", "section": "service", "who": "rubric", "text": "(14 сентября)"},
  {"id": "cu-mol-0503", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Христа Бога нашего, Царице Небеси и земли! Вонми многоболезненному воздыханию душ наших, призри с высоты святыя Твоея на нас, с верою и любовию покланяющихся пречистому образу Твоему: се бо, грехми погружаеми и скорбми обуреваеми, взирающе на Твой образ, яко живущей Ти с нами, приносим смиренная моления наша, не имамы бо иныя помощи, ни инаго предстательства и утешения, токмо Тебе, о, Мати всех скорбящих и обремененных."},
  {"id": "cu-mol-0504", "section": "service", "who": "reader", "text": "Помози нам, немощным, утоли скорбь нашу, настави на путь правый нас, заблудших, уврачуй болезненная сердца наша и спаси безнадежныя. Даруй нам прочее время живота нашего в мире и покаянии проводити, подаждь христианскую кончину и на Страшнем Суде Сына Твоего явися нам милосердая Предстательница, да всегда поем, величаем и славим Тя, яко Благую Заступницу рода христианскаго, со всеми угодившими Богу. Аминь."},
  {"id": "cu-mol-0505", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Черниговской-Ильинской»"},
  {"id": "cu-mol-0506", "section": "service", "who": "rubric", "text": "(29 апреля)"},
  {"id": "cu-mol-0507", "section": "service", "who": "rubric", "text": "Пресвятая Богородице, спаси нас!"},
  {"id": "cu-mol-0508", "section": "service", "who": "reader", "text": "О Пресвятая Госпоже, Владычице моя Богородице, Небесная Царице! Спаси и помилуй мя, грешнаго раба твоего, от напрасныя клеветы, от всякия беды и напасти и внезапныя смерти. Помилуй мя в дневных часех, и утренних, и вечерних, и во всякое время сохрани мя: стояща, седяща соблюди, и на всяком пути ходяща, и в нощных часех спяща снабди, покрый и заступи. Защити мя, Владычице Богородице, от всех враг моих видимых и невидимых и от всякаго злаго обстояния. На всяком месте и на всякое время буди ми, Мати Преблагая, стена необоримая и заступление крепкое."},
  {"id": "cu-mol-0509", "section": "service", "who": "reader", "text": "О, Пресвятая Госпоже, Владычице Дево Богородице! Приими недостойную молитву мою, и сохрани мя от внезапныя смерти, и даруй ми прежде конца покаяние."},
  {"id": "cu-mol-0510", "section": "service", "who": "reader", "text": "Пресвятая Богородице, спаси нас!"},
  {"id": "cu-mol-0511", "section": "service", "who": "reader", "text": "Ты мне Хранительница жизни всея явися, Пречистая; Ты мене избави от бесов в час смерти; Ты и по смерти мене упокой."},
  {"id": "cu-mol-0512", "section": "service", "who": "reader", "text": "Под Твою милость прибегаем, Богородице Дево: молений наших не презри в скорбех, но от бед избави нас, едина Чистая и Благословенная."},
  {"id": "cu-mol-0513", "section": "service", "who": "reader", "text": "Пресвятая Богородице, спаси нас! Аминь."},
  {"id": "cu-mol-0514", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Экономисса»"},
  {"id": "cu-mol-0515", "section": "service", "who": "rubric", "text": "(18 июля)"},
  {"id": "cu-mol-0516", "section": "service", "who": "rubric", "text": "О Пречистая Владычице Богородице, Всечестнейшая наша Мати Игумение всех православных святых обителей иноческаго жития, во Святей Горе Афонстей и по всей вселенней сущих!"},
  {"id": "cu-mol-0517", "section": "service", "who": "reader", "text": "Приими смиренная моления наша и принеси я ко всещедрому Богу нашему, да спасет души наша Своею благодатию. Воззри на ны милосердным Твоим оком и соверши Сама о Господе наше спасение, понеже без милости Спаса нашего и Твоего святаго о нас ходатайства не возможем окаяннии совершити своего спасения, яко окаляхом99 житие наше в суетах мирских, ибо время приближися жатвы Христовы и день Страшнаго Суда приспе."},
  {"id": "cu-mol-0518", "section": "service", "who": "reader", "text": "Мы же, окаяннии, погибаем в бездне греховней нерадения ради нашего, по реченному от святых отцев, первоначальников ангельскаго во плоти жития, яко последнии монаси100 нерадением жития своего уподобятся мирским человеком, еже и сбыся днесь, ибо последнее иночество наше плавает житием своим в мори житейском, посреде великия бури и непогоды, ибо наша святыя обители во прасе пребывают, грехов бо ради наших всеправедный Судия Господь наш Иисус Христос тако благоволи, мы же, недостойнии, не имамы, где главы подклонити."},
  {"id": "cu-mol-0519", "section": "service", "who": "reader", "text": "О, сладчайшая наша Мати Игумение! Собери ны, разсеянное стадо Христово, воедино и спаси православное монашество последняго века сего, и всех православных христиан сподоби райския жизни со ангелы и всеми святыми во Царствии Христа Бога нашего, Емуже честь и слава, со Безначальным Его Отцем и со Пресвятым, Благим и Животворящим Его Духом во веки веков. Аминь."},
  {"id": "cu-mol-0520", "section": "service", "who": "rubric", "text": "Примечания:"},
];

